-- CCN Council Prep Pro: question bank batch 10 (second set of uploaded study files, October 2026)
-- Run this once in the Supabase SQL Editor. It is safe to run again: questions already in the
-- bank (same wording) are skipped, and new IDs are taken after the current highest ID.
--
-- 447 new questions. Every question has exactly 4 options, one correct answer and an explanation.
-- Answers were supplied where the source had none; wrong keys were corrected; true/false, matching,
-- fill-in-the-blank and opinion-style items were left out or rewritten. CCNP Paper I and the Word
-- copy of UMTH Paper I were already in the bank, so they add nothing new.
--
-- Per source (topic):
--   CCU Self-Assessment Practice MCQs: 191
--   Mock Examination 3: 65
--   Anaesthesia Questions & Answers: 29
--   Ethical Principles MCQs: 5
--   Management & Leadership MCQs: 51
--   Chest Tube & Hypothermia MCQs: 17
--   Research Methods MCQs: 15
--   UMTH Prequalifying Practice Set 7: 65
--   Electrical Cardioversion: 9
--
-- New rows are paid content (is_legacy = false, the column default).

insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
select (select coalesce(max(id), 0) from public.questions) + row_number() over (order by v.n),
       v.topic, v.source, v.q, v.opts, v.ans_idx, v.exp, v.category, v.category_icon, true
from (values
(1, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is teaching a group of nursing students about the history of computers. Which generation of computers is characterized by the use of vacuum tubes?', '["First Generation", "Second Generation", "Third Generation", "Fourth Generation"]'::jsonb, 0, 'The First Generation of computers, from 1940 to 1956, were characterized by the use of bulky and energy-inefficient vacuum tubes for circuitry. Second Generation computers used transistors, Third Generation used integrated circuits, and Fourth Generation used microprocessors.', 'Nursing Informatics & ICT', '💻'),
(2, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following units of data is the largest?', '["Megabyte (MB)", "Kilobyte (KB)", "Gigabyte (GB)", "Terabyte (TB)"]'::jsonb, 3, 'A Terabyte is the largest unit listed, equal to about one trillion bytes. The order from smallest to largest is: Kilobyte (about one thousand bytes), Megabyte (about one million bytes), Gigabyte (about one billion bytes), and Terabyte.', 'Nursing Informatics & ICT', '💻'),
(3, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nursing student is learning about the components of a computer. Which of the following is considered an input device?', '["Printer", "Speaker", "Keyboard", "Monitor"]'::jsonb, 2, 'An input device is a peripheral used to send data to a computer. A keyboard is used to input text and commands. A printer, speaker, and monitor are all output devices.', 'Nursing Informatics & ICT', '💻'),
(4, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is documenting a patient''s vital signs on a tablet in a patient''s room. This use of a tablet in healthcare primarily improves:', '["Data storage capacity", "Computer processing speed", "Accessibility and real-time documentation", "Internet security"]'::jsonb, 2, 'Tablets are portable and allow nurses to document directly at the bedside, which improves accessibility and ensures data is entered in real time, enhancing the accuracy and timeliness of the Electronic Health Record (EHR).', 'Nursing Informatics & ICT', '💻'),
(5, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following computer components is known as the "brain" of the computer, responsible for executing instructions?', '["RAM (Random Access Memory)", "ROM (Read-Only Memory)", "CPU (Central Processing Unit)", "Hard Drive"]'::jsonb, 2, 'The CPU is the central processing unit, which is the electronic circuitry that executes instructions and performs the basic arithmetic, logical, control, and input/output (I/O) operations specified by computer programs.', 'Nursing Informatics & ICT', '💻'),
(6, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A hospital is implementing a new EHR system. What is a primary reason for using EHRs in nursing practice?', '["To reduce the number of computers needed in the hospital", "To allow nurses to communicate more easily via email", "To enhance patient safety and provide a comprehensive, longitudinal record", "To decrease the need for secure data storage"]'::jsonb, 2, 'EHRs consolidate all patient information into a single, accessible record, which helps to improve communication among healthcare providers, reduce medication errors, and provide a complete history of the patient''s care, thereby enhancing patient safety.', 'Nursing Informatics & ICT', '💻'),
(7, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is explaining the units of data to a patient. The smallest unit of data in a computer is a:', '["Byte", "Bit", "Kilobyte", "Megabyte"]'::jsonb, 1, 'A bit (binary digit) is the most basic unit of information in computing and is a one or a zero. A byte is a group of 8 bits. The other options are larger units of data.', 'Nursing Informatics & ICT', '💻'),
(8, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'What is the main function of RAM (Random Access Memory) in a computer?', '["To store data permanently", "To store the operating system", "To temporarily store data that the CPU is actively using", "To provide an internet connection"]'::jsonb, 2, 'RAM is a form of computer memory that can be read and changed in any order, typically used to store working data and machine code. When the computer is turned off, the data in RAM is lost.', 'Nursing Informatics & ICT', '💻'),
(9, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is concerned about data security when accessing patient records on a computer. Which of the following is a fundamental principle of data security in healthcare?', '["Using a single, shared password for all computers", "Ensuring all data is stored on a single, non-networked device", "Implementing strong passwords, encryption, and access controls", "Allowing all staff members to have full access to all patient records"]'::jsonb, 2, 'Data security in healthcare requires multiple layers of protection, including strong passwords, data encryption to protect information during transmission and storage, and access controls to ensure only authorized personnel can view patient records.', 'Nursing Informatics & ICT', '💻'),
(10, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which type of computer is most commonly used by nurses for tasks like charting, medication administration, and accessing patient information in a healthcare setting?', '["Supercomputer", "Mainframe computer", "Desktop computer", "Laptop or tablet computer"]'::jsonb, 3, 'Due to their portability and wireless connectivity, laptops and tablets are ideal for bedside charting and real-time documentation, which is crucial for modern nursing practice. Desktop computers are often used in office settings but are less practical for direct patient care.', 'Nursing Informatics & ICT', '💻'),
(11, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is documenting patient information and notices that the file size is very large. The file size is measured in kilobytes (KB), but the nurse needs to know how many bytes are in one kilobyte. The correct answer is:', '["100 bytes", "1,000 bytes", "1,024 bytes", "10,000 bytes"]'::jsonb, 2, 'In computer science, a kilobyte is typically defined as 1,024 bytes (2^{10}), not a round 1,000, due to the binary nature of computers. This is a common point of confusion with the metric system.', 'Nursing Informatics & ICT', '💻'),
(12, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is using an Electronic Health Record (EHR) to access a patient''s lab results. The EHR system provides a centralized location for patient data, which helps to:', '["Increase the time it takes to retrieve patient data", "Ensure each department uses its own unique record system", "Improve continuity of care and coordination among the healthcare team", "Eliminate the need for any verbal communication between nurses"]'::jsonb, 2, 'A centralized EHR allows all members of the healthcare team to access the same, up-to-date information, which streamlines communication, reduces the risk of miscommunication, and ensures a more coordinated and continuous plan of care.', 'Nursing Informatics & ICT', '💻'),
(13, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The main difference between a laptop and a desktop computer is:', '["A desktop is faster than a laptop", "A laptop has a separate monitor, keyboard, and mouse", "A laptop is portable and integrates its monitor, keyboard, and mouse", "A desktop is more expensive than a laptop"]'::jsonb, 2, 'The key distinction is portability. Laptops are designed for mobility and combine all the essential components into a single, compact unit, whereas desktops are stationary and require separate peripherals.', 'Nursing Informatics & ICT', '💻'),
(14, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following is an example of a Fifth Generation computer characteristic?', '["Use of integrated circuits", "Use of vacuum tubes", "Use of artificial intelligence (AI) and natural language processing", "Use of transistors"]'::jsonb, 2, 'Fifth-generation computing, which is still in development, is based on AI and aims to allow computers to understand human language and make decisions, using advancements in parallel processing and superconductors.', 'Nursing Informatics & ICT', '💻'),
(15, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is discussing the importance of data storage with a patient. What is the primary function of a hard drive in a computer?', '["To execute computer programs", "To provide temporary working memory", "To store data and programs permanently", "To display visual information"]'::jsonb, 2, 'Hard drives are a type of non-volatile storage, meaning they retain data even when the computer is turned off. They are used to store the operating system, applications, and all the user''s files.', 'Nursing Informatics & ICT', '💻'),
(16, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nursing informatics specialist is educating new nurses about the role of computers in healthcare. The use of computers in nursing can help to:', '["Eliminate the need for human judgment in clinical decision-making", "Increase the administrative burden on nurses", "Automate routine tasks and provide access to evidence-based practice guidelines", "Decrease the security of patient health information"]'::jsonb, 2, 'Computer systems, such as EHRs, can automate tasks like scheduling and documentation. They also provide tools that integrate clinical decision support, giving nurses easy access to the latest research and guidelines to inform their practice.', 'Nursing Informatics & ICT', '💻'),
(17, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following is a risk associated with the use of portable tablets for documentation in a busy clinical setting?', '["The tablet screen is too small to view information", "The tablets are too heavy for nurses to carry", "They are susceptible to being lost, stolen, or damaged", "They require constant access to a wired internet connection"]'::jsonb, 2, 'Due to their portability, tablets and other mobile devices have a higher risk of being misplaced or stolen. This poses a significant data security risk, as a stolen device could contain sensitive patient health information.', 'Nursing Informatics & ICT', '💻'),
(18, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is setting up a new computer station in a clinic. Which of the following is considered an output device?', '["Mouse", "Scanner", "Microphone", "Printer"]'::jsonb, 3, 'An output device receives data from a computer. A printer produces a hard copy of a document. A mouse, scanner, and microphone are all input devices used to send information into the computer.', 'Nursing Informatics & ICT', '💻'),
(19, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Why is data security an essential consideration when using computers in nursing practice?', '["To ensure that computers never crash", "To prevent unauthorized access to confidential patient information", "To speed up the computer''s processing time", "To make the EHR system more difficult to use"]'::jsonb, 1, 'Data security is crucial in healthcare to protect patient privacy and comply with regulations like HIPAA. Unauthorized access to health information can lead to identity theft, fraud, and a breach of trust between the patient and the healthcare provider.', 'Nursing Informatics & ICT', '💻'),
(20, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'What is the purpose of an Electronic Health Record (EHR)?', '["To store only the patient''s demographic information", "To serve as a paper-based filing system", "To create a digital version of a patient''s chart", "To replace the need for any patient-nurse interaction"]'::jsonb, 2, 'The EHR is a digital version of a patient’s paper chart. It includes a comprehensive record of a patient’s medical history, diagnoses, medications, treatment plans, immunization dates, allergies, radiology images, and lab and test results.', 'Nursing Informatics & ICT', '💻'),
(21, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following is a key indication for initiating Total Parenteral Nutrition (TPN)?', '["Short-term use in a patient who is post-operative and can tolerate oral intake", "An unconscious patient with an intact gastrointestinal (GI) tract", "A patient with a non-functioning gastrointestinal tract who is unable to absorb nutrients", "A patient requiring a low-protein diet"]'::jsonb, 2, 'A non-functioning GI tract is a primary indication for TPN, as the patient cannot absorb nutrients via the enteral route. If the GI tract is intact, enteral nutrition is the preferred and safer method.', 'GI, Endocrine & Metabolic', '🍽️'),
(22, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is monitoring a patient on TPN. Which of the following is an early sign of a catheter-related blood stream infection (CRBSI)?', '["Hyperglycemia", "Fever and chills", "Refeeding syndrome", "Hypocalcemia"]'::jsonb, 1, 'Fever and chills are classic systemic signs of infection and should prompt an investigation for a CRBSI. Hyperglycemia can occur for other reasons, and refeeding syndrome is a metabolic complication, not an infection.', 'GI, Endocrine & Metabolic', '🍽️'),
(23, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient on TPN is showing signs of fluid volume excess. Which of the following nursing interventions is most appropriate?', '["Increasing the TPN infusion rate", "Notifying the provider to decrease the fluid rate", "Administering a bolus of intravenous fluids", "Monitoring the patient''s blood glucose levels"]'::jsonb, 1, 'If a patient shows signs of fluid volume excess (e.g., crackles, edema), the nurse should immediately notify the provider so the TPN infusion rate or the fluid components can be adjusted to prevent further complications like heart failure.', 'GI, Endocrine & Metabolic', '🍽️'),
(24, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient on TPN is at risk for refeeding syndrome. The nurse should be most vigilant for which of the following electrolyte imbalances?', '["Hypernatremia", "Hyperkalemia", "Hypophosphatemia", "Hypocalcemia"]'::jsonb, 2, 'Refeeding syndrome is a potentially fatal shift in fluid and electrolytes that can occur in malnourished patients receiving aggressive nutritional support. It is characterized by severe hypophosphatemia, hypokalemia, and hypomagnesemia.', 'GI, Endocrine & Metabolic', '🍽️'),
(25, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is preparing to administer TPN. What is the most important nursing responsibility before starting the infusion?', '["Checking the patient''s blood pressure", "Verifying the TPN solution with another nurse", "Administering a dose of insulin", "Documenting the patient''s height and weight"]'::jsonb, 1, 'TPN is a high-risk medication due to its complexity. A critical safety measure is to have a second nurse independently verify the TPN solution against the provider''s order to prevent medication errors.', 'GI, Endocrine & Metabolic', '🍽️'),
(26, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following components is a primary source of carbohydrates in TPN?', '["Amino acids", "Dextrose", "Lipids", "Vitamins"]'::jsonb, 1, 'Dextrose, a form of glucose, is the main source of carbohydrates and calories in a TPN solution. Amino acids provide protein, lipids provide fat, and vitamins are also included for essential nutrients.', 'GI, Endocrine & Metabolic', '🍽️'),
(27, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient receiving TPN. What is the highest priority nursing intervention to prevent infection?', '["Changing the TPN bag every 12 hours", "Using aseptic technique for all line manipulations", "Monitoring the patient''s intake and output", "Administering prophylactic antibiotics"]'::jsonb, 1, 'Aseptic technique is the most critical intervention to prevent infection, as TPN solutions are a perfect medium for bacterial growth and the central line provides a direct route into the bloodstream.', 'GI, Endocrine & Metabolic', '🍽️'),
(28, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse notes that a patient on TPN has a blood glucose level of 250 mg/dL. The most likely cause is:', '["Refeeding syndrome", "A low infusion rate", "The patient''s inability to metabolize the high glucose load", "A contaminated TPN bag"]'::jsonb, 2, 'TPN contains a high concentration of dextrose. Hyperglycemia is a very common complication, especially in patients who are diabetic or have a reduced tolerance for glucose. This is not directly caused by refeeding syndrome or a low infusion rate.', 'GI, Endocrine & Metabolic', '🍽️'),
(29, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient''s TPN is discontinued. What is the most appropriate nursing action to prevent a rapid drop in blood glucose (hypoglycemia)?', '["Immediately capping the central line", "Decreasing the TPN rate to half for 24 hours", "Hanging a bag of D10W (10% Dextrose in Water)", "Administering a dose of insulin"]'::jsonb, 2, 'When TPN is abruptly discontinued, the pancreas, which has been producing a high level of insulin to handle the concentrated glucose, can continue to produce too much insulin, leading to rebound hypoglycemia. Hanging D10W prevents this by providing a temporary glucose source.', 'GI, Endocrine & Metabolic', '🍽️'),
(30, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is teaching a new graduate nurse about the safe administration of TPN. The nurse should emphasize that the TPN solution should never be:', '["Stored in the refrigerator", "Administered through a peripheral IV line", "Filtered before administration", "Given at a slow, continuous rate"]'::jsonb, 1, 'TPN is a hypertonic solution and is very irritating to peripheral veins, which can cause phlebitis. TPN should only be administered through a central venous catheter to ensure proper dilution and to prevent damage to the veins.', 'GI, Endocrine & Metabolic', '🍽️'),
(31, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient on TPN has a history of heart failure. The nurse should be vigilant for signs of:', '["Fluid volume deficit", "Catheter-related infection", "Hyperglycemia", "Fluid volume excess"]'::jsonb, 3, 'Patients with heart failure have a reduced ability to handle large fluid volumes. The high volume of TPN, especially if the rate is too fast, can easily lead to fluid volume excess, which can worsen their heart failure.', 'GI, Endocrine & Metabolic', '🍽️'),
(32, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is preparing to change the dressing on a central line used for TPN. What type of dressing is most appropriate?', '["A simple gauze dressing", "A transparent, semipermeable membrane dressing", "An occlusive dressing with petroleum jelly", "A bandage with adhesive tape"]'::jsonb, 1, 'A transparent dressing allows the nurse to visualize the insertion site for signs of infection without removing the dressing. It also provides a barrier against external contaminants while allowing the skin to breathe.', 'GI, Endocrine & Metabolic', '🍽️'),
(33, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'When monitoring a patient on TPN, the nurse should assess for signs of electrolyte imbalances, which include:', '["Stable weight", "Clear lung sounds", "Muscle weakness and cardiac arrhythmias", "Normal blood glucose levels"]'::jsonb, 2, 'TPN can cause significant electrolyte shifts, particularly in potassium, magnesium, and phosphate. These imbalances can manifest as muscle weakness, fatigue, and, most dangerously, cardiac arrhythmias.', 'GI, Endocrine & Metabolic', '🍽️'),
(34, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse finds the TPN bag has been hanging for 26 hours. The most appropriate nursing action is to:', '["Slow the infusion rate until the new bag arrives", "Continue the infusion as it is still safe", "Discard the current bag and obtain a new one", "Clamp the line and flush it with saline"]'::jsonb, 2, 'TPN solutions are a high-risk medium for bacterial growth. They should be changed every 24 hours to prevent the risk of a central line-associated bloodstream infection (CLABSI). The current bag should be discarded and a new one obtained.', 'GI, Endocrine & Metabolic', '🍽️'),
(35, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is providing education to a patient''s family about TPN. The nurse should explain that TPN is:', '["A type of tube feeding", "A nutritional support delivered through the stomach", "A method of providing nutrition through a vein", "A medication used to treat infections"]'::jsonb, 2, 'Total Parenteral Nutrition is the intravenous administration of nutrition, which includes carbohydrates, proteins, fats, vitamins, and minerals. It bypasses the gastrointestinal tract completely.', 'GI, Endocrine & Metabolic', '🍽️'),
(36, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient on TPN suddenly develops chest pain and shortness of breath. The nurse suspects an air embolism. The priority nursing action is to:', '["Elevate the head of the bed", "Place the patient in the Trendelenburg position on their left side", "Administer oxygen", "Slow the TPN infusion rate"]'::jsonb, 1, 'Placing the patient in a left-sided Trendelenburg position traps the air in the right atrium, preventing it from entering the pulmonary circulation and causing a pulmonary embolism. The nurse should then clamp the line and call for help.', 'GI, Endocrine & Metabolic', '🍽️'),
(37, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient on TPN is receiving insulin. What is the primary reason for adding insulin to a TPN solution?', '["To prevent refeeding syndrome", "To increase the absorption of nutrients", "To manage the high glucose load from the TPN solution", "To treat a pre-existing insulin resistance"]'::jsonb, 2, 'TPN solutions contain high concentrations of dextrose. Insulin is often added to the bag to help the body metabolize this glucose and prevent hyperglycemia, which is a common and dangerous complication of TPN.', 'GI, Endocrine & Metabolic', '🍽️'),
(38, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is preparing to change the TPN tubing. The nurse knows that the tubing should be changed:', '["Daily, with each new TPN bag", "Every 72 hours", "Once a week", "Only if it is visibly soiled"]'::jsonb, 0, 'TPN tubing is a high-risk source for bacterial growth and should be changed with every new bag of TPN solution, typically every 24 hours, to reduce the risk of a central line-associated bloodstream infection.', 'GI, Endocrine & Metabolic', '🍽️'),
(39, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient''s TPN infusion is running late. The nurse should:', '["Increase the infusion rate to catch up", "Stop the infusion until the next scheduled time", "Hang the TPN at the current ordered rate and adjust the schedule accordingly", "Call the pharmacist to order a new TPN bag"]'::jsonb, 2, 'The nurse should never increase the infusion rate to "catch up" on a late TPN bag, as this can cause a rapid increase in blood glucose and lead to hyperglycemia and osmotic diuresis. The infusion should be hung at the correct rate, and the healthcare team should be notified to adjust the schedule or orders.', 'GI, Endocrine & Metabolic', '🍽️'),
(40, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'When administering a TPN solution, a nurse must verify that it contains all the prescribed components. What are the three main macronutrients provided in TPN?', '["Water, electrolytes, and vitamins", "Carbohydrates, proteins, and fats", "Sodium, potassium, and chloride", "Dextrose, amino acids, and lipids"]'::jsonb, 3, 'The three main macronutrient components of TPN are Dextrose (for carbohydrates), Amino Acids (for proteins), and Lipids (for fats). Water, electrolytes, and vitamins are also essential but are not considered macronutrients.', 'GI, Endocrine & Metabolic', '🍽️'),
(41, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'What is the primary purpose of a nursing audit?', '["To identify and punish nurses who make mistakes in documentation", "To evaluate the quality of nursing care and identify areas for improvement", "To compare the performance of different nurses in a hospital", "To ensure that all nurses are working the correct number of hours"]'::jsonb, 1, 'A nursing audit systematically reviews nursing records to assess the quality of care provided and to pinpoint opportunities for enhancement. Its focus is on system-wide improvement, not on individual punishment.', 'Ethics, Law & Management', '⚖️'),
(42, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A retrospective nursing audit involves reviewing records:', '["During the care of the patient", "After the patient has been discharged", "Before the patient is admitted to the hospital", "To plan the patient''s care before it begins"]'::jsonb, 1, 'A retrospective audit is a type of quality assurance that involves reviewing documentation after a patient''s episode of care has been completed. This allows for a comprehensive review of the entire process.', 'Ethics, Law & Management', '⚖️'),
(43, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following is an example of a quality indicator in nursing care?', '["The number of beds in the hospital", "The number of nurses on the night shift", "The rate of hospital-acquired pressure ulcers", "The color of the hospital uniforms"]'::jsonb, 2, 'A quality indicator is a measurable element of patient care that can be used to assess the quality of a service. The rate of hospital-acquired pressure ulcers is a direct measure of the quality of nursing care provided, particularly in skin and wound care.', 'Ethics, Law & Management', '⚖️'),
(44, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nursing audit is being conducted on a hospital unit. The audit reveals a high rate of medication errors. The most appropriate action is to:', '["Fire the nurses who made the errors", "Implement a new policy for medication administration and provide staff education", "Ignore the results as a normal part of nursing", "Blame the pharmacists for providing the wrong medications"]'::jsonb, 1, 'The purpose of an audit is to improve care, not to punish. A high error rate points to a systemic issue that requires a system-level solution, such as a new policy, training, or a review of the medication administration process.', 'Ethics, Law & Management', '⚖️'),
(45, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The type of audit that involves reviewing a patient''s chart while they are still in the hospital is called a:', '["Retrospective audit", "Concurrent audit", "Prospective audit", "Outcome audit"]'::jsonb, 1, 'A concurrent audit occurs simultaneously with the patient''s care. This allows for real-time intervention and can help to prevent potential problems before they lead to poor patient outcomes.', 'Ethics, Law & Management', '⚖️'),
(46, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'What is the main role of a nurse in maintaining standards and documentation for quality assurance?', '["To only document when asked to by the charge nurse", "To ensure all documentation is complete, accurate, and timely", "To only document positive patient outcomes", "To ignore any errors found in the documentation"]'::jsonb, 1, 'Accurate and timely documentation is the foundation of a nursing audit. It provides the data needed to evaluate the quality of care, identify trends, and make informed decisions about improving patient outcomes.', 'Ethics, Law & Management', '⚖️'),
(47, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A hospital is performing an outcome audit. This type of audit focuses on:', '["The patient''s diagnosis", "The staff-to-patient ratio", "The patient''s overall health status at discharge", "The cost of the patient''s care"]'::jsonb, 2, 'An outcome audit measures the end result of care. It assesses whether the patient''s condition improved or whether a negative outcome (e.g., infection) occurred as a result of the care provided.', 'Ethics, Law & Management', '⚖️'),
(48, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nursing audit reveals that many nurses are not completing the required pain assessment documentation. The next step in quality assurance should be to:', '["Punish the nurses who failed to document", "Provide a refresher course on pain assessment and documentation", "Change the pain assessment policy", "Tell the patients to complain if their pain is not assessed"]'::jsonb, 1, 'A lack of proper documentation suggests a need for education or a review of the process. Providing a refresher course is a constructive approach to improving practice and ensuring compliance with the hospital''s standards.', 'Ethics, Law & Management', '⚖️'),
(49, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following is the best example of a structural quality indicator?', '["The number of patient falls", "The number of nurses with advanced certifications", "The patient''s satisfaction with care", "The number of surgical site infections"]'::jsonb, 1, 'Structural indicators measure the context in which care is delivered. This includes the resources, staffing levels, and environment. The number of nurses with advanced certifications is a measure of the professional qualifications of the staff, which is a structural element.', 'Ethics, Law & Management', '⚖️'),
(50, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nursing manager is using a concurrent audit to identify potential issues with patient care. The advantage of a concurrent audit is that it allows for:', '["A review of care after the patient has been discharged", "Immediate intervention to correct a problem", "The collection of a large amount of data from many patients at once", "A historical analysis of care over a long period"]'::jsonb, 1, 'Since a concurrent audit is performed while the patient is still receiving care, it provides an opportunity to identify and address issues in real time, preventing a poor outcome or improving the quality of care on the spot.', 'Ethics, Law & Management', '⚖️'),
(51, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A hospital''s quality assurance team is performing a prospective audit. This audit would involve:', '["Reviewing the outcomes of a patient''s treatment after they leave the hospital", "Examining the care provided to a patient in real-time", "Reviewing and establishing new policies and procedures before they are implemented", "Analyzing a patient''s chart after a critical event has occurred"]'::jsonb, 2, 'A prospective audit looks at the future. It involves the evaluation of proposed policies, procedures, or care plans before they are put into practice to ensure they meet quality standards and are likely to lead to positive outcomes.', 'Ethics, Law & Management', '⚖️'),
(52, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The goal of quality assurance in nursing is to:', '["Reduce the cost of care", "Meet the minimum legal standards of care", "Continuously improve patient care and outcomes", "Ensure nurses follow all orders without question"]'::jsonb, 2, 'The ultimate goal of quality assurance is to provide the best possible care for patients. This involves a continuous cycle of evaluating care, identifying opportunities for improvement, and implementing changes to enhance patient safety and outcomes.', 'Ethics, Law & Management', '⚖️'),
(53, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'An example of a process quality indicator is:', '["The presence of a CPR cart on the unit", "The percentage of patients who receive a fall risk assessment on admission", "The patient''s length of stay in the hospital", "The hospital''s overall readmission rate"]'::jsonb, 1, 'A process indicator measures a specific nursing activity or intervention. It assesses whether the proper procedure was followed. Performing a fall risk assessment is a specific process that can be measured.', 'Ethics, Law & Management', '⚖️'),
(54, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse manager uses the results of a nursing audit to make changes to the unit''s policies. This is an example of the nurse''s role in:', '["Punishing staff for poor performance", "Maintaining the status quo", "Quality improvement", "Disregarding the documentation process"]'::jsonb, 2, 'Using audit results to make changes is the core of quality improvement. It demonstrates a commitment to learning from past performance and proactively implementing changes to enhance the quality of care.', 'Ethics, Law & Management', '⚖️'),
(55, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nursing audit can help to identify:', '["The nurse who is the \"best\" at their job", "The single cause of all patient complications", "Trends in patient care that may need to be addressed", "The hospital''s financial status"]'::jsonb, 2, 'Audits are designed to identify patterns and trends in care. For example, an audit might reveal a high number of urinary tract infections on a unit, which would prompt an investigation into the care process to identify the root cause and implement corrective actions.', 'Ethics, Law & Management', '⚖️'),
(56, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The documentation of a nursing audit should include:', '["Only the names of the nurses who made errors", "A detailed report of the findings, including recommendations for change", "The names of all the patients whose charts were reviewed", "A simple ''pass'' or ''fail'' grade for the unit"]'::jsonb, 1, 'The audit report should be a comprehensive document that outlines the findings of the audit, identifies areas of strength and weakness, and provides a clear plan of action with specific recommendations for improving quality.', 'Ethics, Law & Management', '⚖️'),
(57, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nursing audit is a tool for:', '["Blame and punishment", "Retrospective documentation", "Quality control and assurance", "Patient complaint management"]'::jsonb, 2, 'A nursing audit is a systematic process used for quality control. It provides the data necessary to ensure that the standards of care are being met and to identify opportunities to improve the quality of care, which is the goal of quality assurance.', 'Ethics, Law & Management', '⚖️'),
(58, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'What is the main difference between an audit and a peer review?', '["An audit is performed by an external body, while a peer review is done by a manager.", "An audit is a systematic evaluation of records, while a peer review is an evaluation of an individual''s practice by other nurses.", "A peer review is a punitive process, while an audit is not.", "An audit only focuses on documentation, while a peer review focuses on patient outcomes."]'::jsonb, 1, 'A nursing audit is a formal process for evaluating documentation and care processes against a standard. Peer review is a process where a nurse''s professional practice is evaluated by other nurses, typically with the goal of professional development and improvement.', 'Ethics, Law & Management', '⚖️'),
(59, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse manager wants to assess the compliance of staff with a new hand hygiene protocol. Which type of audit would be most effective for this purpose?', '["Retrospective audit", "Concurrent audit", "Outcome audit", "Chart audit"]'::jsonb, 1, 'A concurrent audit would be the most effective as it would allow the manager to observe the nurses'' hand hygiene practices in real-time, providing immediate feedback and a direct measure of compliance with the new protocol.', 'Ethics, Law & Management', '⚖️'),
(60, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'An audit on a surgical unit reveals an increase in surgical site infections. This finding is an example of an audit of:', '["Structure", "Process", "Outcome", "Policy"]'::jsonb, 2, 'The surgical site infection rate is an outcome measure. It assesses the end result of the care provided and indicates whether the processes (e.g., sterile technique) and structure (e.g., resources) were effective in preventing a negative patient outcome.', 'Ethics, Law & Management', '⚖️'),
(61, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'When assessing the neurological status of an unconscious patient, which component of the Glasgow Coma Scale (GCS) is used to evaluate eye opening?', '["Verbal Response", "Motor Response", "Pupillary Response", "Eye Opening"]'::jsonb, 3, 'The GCS is a neurological scale that assesses a patient''s level of consciousness. The three main components are eye opening, verbal response, and motor response. Pupillary response is a separate neurological assessment.', 'Neurology', '🧠'),
(62, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for an unconscious patient. Which of the following is a priority nursing intervention to prevent complications?', '["Administering oral fluids every hour", "Leaving the patient in the same position for extended periods", "Performing frequent oral care and airway suctioning", "Encouraging the patient to cough and deep breathe"]'::jsonb, 2, 'Airway management is a priority for unconscious patients to prevent aspiration and maintain oxygenation. Oral care and suctioning are vital to remove secretions and maintain a patent airway. The other options are incorrect and potentially harmful.', 'Neurology', '🧠'),
(63, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is assessing an unconscious patient and notes a GCS score of 3. This score indicates:', '["Mild head injury", "Moderate head injury", "Severe head injury or a comatose state", "The patient is fully conscious and alert"]'::jsonb, 2, 'The lowest possible GCS score is 3, which is a state of deep unconsciousness, often defined as a coma. Scores of 13-15 are considered mild, 9-12 are moderate, and 3-8 are severe.', 'Neurology', '🧠'),
(64, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is providing care for an unconscious patient. To prevent deep vein thrombosis (DVT), the nurse should:', '["Administer an anticoagulant medication", "Encourage the patient to walk every 2 hours", "Place the patient in a prone position", "Apply sequential compression devices (SCDs) or perform range-of-motion exercises"]'::jsonb, 3, 'Unconscious patients are at high risk for DVT due to immobility. SCDs and passive range-of-motion exercises help to promote blood circulation in the legs, reducing the risk of clot formation.', 'Neurology', '🧠'),
(65, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is providing eye care for an unconscious patient. The primary reason for this care is to prevent:', '["Corneal abrasions and ulcerations", "Glaucoma", "Cataracts", "Retinal detachment"]'::jsonb, 0, 'Unconscious patients may have a diminished or absent blink reflex, leaving their eyes susceptible to drying and damage. Regular eye care, including the use of artificial tears, is essential to keep the cornea moist and protected.', 'Neurology', '🧠'),
(66, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is providing skin care for an unconscious patient. What is the most effective intervention to prevent pressure ulcers?', '["Applying a thick layer of lotion to the skin", "Repositioning the patient every 2 hours", "Massaging reddened areas of the skin", "Using a firm mattress on the bed"]'::jsonb, 1, 'Frequent repositioning is the most effective way to prevent pressure ulcers. It relieves pressure on bony prominences and allows for proper blood flow to the skin. Massaging reddened areas can cause further damage, and a firm mattress is not ideal.', 'Neurology', '🧠'),
(67, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is managing the nutrition of an unconscious patient. The most appropriate method of nutrition support is:', '["Oral feeding with pureed foods", "Intravenous fluids only", "Enteral feeding via a nasogastric or gastrostomy tube", "Total Parenteral Nutrition (TPN)"]'::jsonb, 2, 'Enteral feeding is the preferred method of nutritional support for unconscious patients with an intact gastrointestinal tract. It is safer, more physiologic, and less expensive than TPN, and oral feeding is not possible due to the risk of aspiration.', 'Neurology', '🧠'),
(68, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is preparing to suction the airway of an unconscious patient. The nurse should be aware that excessive suctioning can lead to:', '["Hypertension and tachycardia", "Hyperventilation and respiratory alkalosis", "Hypoxemia and cardiac arrhythmias", "Increased intracranial pressure"]'::jsonb, 2, 'Excessive or prolonged suctioning can remove oxygen from the patient''s lungs, leading to hypoxemia. This can cause the heart rate to slow down, potentially leading to dangerous cardiac arrhythmias.', 'Neurology', '🧠'),
(69, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'When assessing an unconscious patient, a nurse notices a change in the patient''s breathing pattern, with periods of apnea alternating with deep breaths. This is known as:', '["Kussmaul breathing", "Cheyne-Stokes respiration", "Ataxic breathing", "Apneustic breathing"]'::jsonb, 1, 'Cheyne-Stokes respiration is a specific abnormal breathing pattern characterized by a gradual increase in breathing depth and rate, followed by a gradual decrease, and then a period of apnea. It is often associated with severe neurological dysfunction.', 'Neurology', '🧠'),
(70, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is monitoring an unconscious patient for signs of increased intracranial pressure (ICP). Early signs of increased ICP include:', '["A sudden increase in blood pressure", "Bradycardia", "Change in the level of consciousness", "Widened pulse pressure"]'::jsonb, 2, 'A change in the level of consciousness, such as restlessness, confusion, or a decreased GCS score, is often the earliest and most subtle sign of increasing ICP. The other options are part of Cushing''s triad, which are later, more severe signs.', 'Neurology', '🧠'),
(71, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is performing hygiene care for an unconscious patient. To prevent complications, the nurse should:', '["Bathe the patient with cold water to stimulate a response", "Use a cotton swab to clean the patient''s ears", "Ensure the patient''s head is elevated to at least 30 degrees during care", "Use a firm bristle toothbrush to clean the teeth"]'::jsonb, 2, 'Elevating the head of the bed helps to reduce the risk of aspiration and also helps to decrease intracranial pressure. The other options are either unsafe or ineffective for an unconscious patient.', 'Neurology', '🧠'),
(72, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is planning care for an unconscious patient to prevent contractures. The most effective intervention is:', '["Placing the patient in a single, comfortable position", "Administering muscle relaxants", "Performing passive range-of-motion (ROM) exercises to all joints", "Taping the patient''s limbs in a neutral position"]'::jsonb, 2, 'Passive ROM exercises are essential for maintaining joint mobility and muscle length, preventing contractures and muscle atrophy. This should be a regular part of the patient''s care.', 'Neurology', '🧠'),
(73, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is assessing the nutritional status of an unconscious patient. Which of the following is an important indicator to monitor?', '["Blood pressure", "Intake and output (I&O) and weight", "Body temperature", "Pain level"]'::jsonb, 1, 'Monitoring the patient''s I&O and daily weight provides crucial information about their fluid balance and whether the nutritional support they are receiving is adequate. This helps to prevent malnutrition and fluid volume imbalances.', 'Neurology', '🧠'),
(74, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is preparing to insert a nasogastric tube for nutrition in an unconscious patient. The nurse must first:', '["Lubricate the tube and insert it quickly", "Elevate the patient''s head to at least 30 degrees", "Obtain a chest x-ray", "Auscultate for bowel sounds"]'::jsonb, 1, 'Before inserting a nasogastric tube, the nurse must elevate the head of the bed to at least 30 degrees to reduce the risk of aspiration during the insertion process. A chest x-ray is required to confirm placement, but this is done after insertion.', 'Neurology', '🧠'),
(75, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is monitoring the temperature of an unconscious patient. A sudden, unexplained rise in temperature may be a sign of:', '["Hypoglycemia", "Infection or damage to the hypothalamus", "Deep vein thrombosis", "Fluid volume overload"]'::jsonb, 1, 'A sudden and unexplained rise in temperature is a key sign of infection. It can also indicate damage to the hypothalamus, the part of the brain that controls body temperature, which is a concern in patients with a severe head injury.', 'Neurology', '🧠'),
(76, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'When managing an unconscious patient, the nurse should be aware that the most significant risk associated with impaired consciousness is:', '["Hypothermia", "Hypotension", "Aspiration", "Hyperglycemia"]'::jsonb, 2, 'The most significant risk for an unconscious patient is aspiration, due to the loss of protective airway reflexes (cough and gag reflex). Aspiration of gastric contents can lead to life-threatening aspiration pneumonia.', 'Neurology', '🧠'),
(77, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is communicating with the family of an unconscious patient. The most therapeutic approach is to:', '["Discourage the family from visiting to allow the patient to rest", "Provide an honest assessment of the patient''s condition and encourage the family to talk to the patient", "Give them false hope about the patient''s recovery", "Only communicate with one designated family member"]'::jsonb, 1, 'Providing honest, yet compassionate, information and encouraging the family to interact with the patient (even though the patient cannot respond) can provide comfort to the family and is a key component of family-centered care.', 'Neurology', '🧠'),
(78, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is positioning an unconscious patient. The patient''s head should be maintained in a:', '["Rotated position to the side", "Flexed position on the chest", "Neutral, midline position", "Hyperextended position"]'::jsonb, 2, 'Maintaining the head in a neutral, midline position helps to ensure venous drainage from the head, which can help to prevent an increase in intracranial pressure. Any flexion or rotation can impede blood flow.', 'Neurology', '🧠'),
(79, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is assessing the pupils of an unconscious patient and notes that they are unequal in size. This finding is known as:', '["Miosis", "Mydriasis", "Anisocoria", "Hippus"]'::jsonb, 2, 'Anisocoria is the term for pupils of unequal size. It is a significant neurological finding in an unconscious patient that may indicate a serious intracranial issue, such as a cranial nerve compression or a mass.', 'Neurology', '🧠'),
(80, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'An unconscious patient is receiving mechanical ventilation. The nurse''s role includes:', '["Turning off the ventilator to check the patient''s breathing", "Only monitoring the patient''s blood pressure", "Suctioning the endotracheal tube as needed and monitoring ventilator settings", "Administering a high dose of sedatives every hour"]'::jsonb, 2, 'The nurse''s role in caring for a mechanically ventilated patient is comprehensive. It includes ensuring the airway is clear through suctioning, monitoring the patient''s response to the ventilator, and ensuring the ventilator settings are correct. The other options are either unsafe or incomplete.', 'Neurology', '🧠'),
(81, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient with a pneumothorax is on Underwater Seal Drainage (UWSD). The nurse observes continuous bubbling in the water-seal chamber. What is the most likely cause?', '["The patient''s lung is fully expanded", "There is a persistent air leak in the pleural space", "The suction is turned off", "The chest tube is kinked"]'::jsonb, 1, 'Continuous bubbling in the water-seal chamber indicates that air is still leaking from the lung into the pleural space. Once the air leak has resolved and the lung is expanded, the bubbling should cease or become minimal.', 'Respiratory', '🫁'),
(82, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'What is the primary purpose of the underwater seal in a UWSD system?', '["To measure the amount of fluid drained from the chest", "To prevent air from re-entering the pleural space", "To apply negative pressure to the chest cavity", "To collect the drainage from the pleural space"]'::jsonb, 1, 'The water seal acts as a one-way valve, allowing air and fluid to exit the chest cavity but preventing air from being sucked back in, which would worsen the pneumothorax.', 'Respiratory', '🫁'),
(83, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient with a chest tube connected to UWSD. The nurse notices the drainage has stopped. What is the most appropriate initial nursing action?', '["Clamp the chest tube and call the physician", "Increase the suction to the system", "Check for kinks in the tubing and reposition the patient", "Remove the chest tube"]'::jsonb, 2, 'A sudden cessation of drainage may be caused by a kinked tube or the patient''s position obstructing the flow. The nurse should first troubleshoot the system by checking for kinks and repositioning the patient before escalating the issue to the physician. Removing the tube would be an unsafe action.', 'Respiratory', '🫁'),
(84, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is assessing a patient with a UWSD system and notes that the water-seal chamber is not fluctuating with the patient''s respirations. What is this finding called?', '["Bubbling", "Tidaling", "Intermittent bubbling", "Cessation of tidaling"]'::jsonb, 3, 'Tidaling is the normal fluctuation of the fluid level in the water-seal chamber with the patient''s breathing. The cessation of tidaling can indicate that the chest tube is occluded or that the patient''s lung has re-expanded.', 'Respiratory', '🫁'),
(85, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient with a chest tube is being prepared for transport. Before transport, the nurse should:', '["Clamp the chest tube for the duration of the transport", "Disconnect the UWSD system", "Ensure the UWSD system is below the level of the patient''s chest", "Remove the chest tube"]'::jsonb, 2, 'The UWSD system must remain below the level of the chest to use gravity to facilitate drainage. Clamping the tube is generally contraindicated unless a specific protocol is in place, as it can cause a tension pneumothorax. Disconnecting or removing the tube is also unsafe.', 'Respiratory', '🫁'),
(86, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient with a chest tube and a UWSD. The nurse notices the patient has pulled the chest tube out. The first action the nurse should take is to:', '["Reinsert the chest tube immediately", "Cover the insertion site with a sterile occlusive dressing, taped on three sides", "Cover the insertion site with a clean gauze pad", "Take the patient''s vital signs"]'::jsonb, 1, 'If the chest tube is accidentally removed, the priority is to prevent air from entering the chest cavity and causing a tension pneumothorax. Covering the site with an occlusive dressing, taped on three sides, creates a one-way valve, allowing air to escape but not to enter.', 'Respiratory', '🫁'),
(87, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is monitoring the drainage from a UWSD. The nurse should report which of the following findings to the physician immediately?', '["Clear, serous fluid", "A sudden increase of bloody drainage", "Intermittent bubbling in the water-seal chamber", "The presence of a small amount of drainage"]'::jsonb, 1, 'A sudden increase in the amount of bloody drainage, particularly if it is bright red, can be a sign of active bleeding in the chest cavity, which is a medical emergency. The other options are considered normal findings or can be addressed by the nurse.', 'Respiratory', '🫁'),
(88, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is preparing to remove a chest tube. Before the removal, the nurse should instruct the patient to perform which of the following?', '["To hold their breath and cough forcefully", "To exhale and bear down (Valsalva maneuver)", "To breathe normally and shallowly", "To perform deep breaths"]'::jsonb, 1, 'The Valsalva maneuver, which involves exhaling and bearing down, increases intrathoracic pressure. This helps to prevent air from being sucked into the chest cavity as the tube is being removed.', 'Respiratory', '🫁'),
(89, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient with a UWSD system. The suction control chamber is bubbling vigorously. The nurse should:', '["Increase the suction to the wall", "Decrease the suction to the wall until gentle bubbling is present", "Clamp the chest tube", "Add more sterile water to the chamber"]'::jsonb, 1, 'Vigorous bubbling in the suction control chamber does not increase suction. It only causes the water to evaporate more quickly and creates unnecessary noise. The suction should be adjusted so that there is only gentle bubbling.', 'Respiratory', '🫁'),
(90, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is assessing a patient with a UWSD for a hemothorax. The nurse knows that the UWSD is primarily used to:', '["Drain air from the pleural space", "Drain blood and fluid from the pleural space", "Provide oxygen to the patient", "Provide a pathway for medication administration"]'::jsonb, 1, 'While UWSD can also drain air, its primary purpose in a hemothorax is to drain the accumulated blood and fluid from the pleural space, allowing the lung to re-expand and preventing complications.', 'Respiratory', '🫁'),
(91, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is caring for a patient with a UWSD. The nurse notices the water-seal chamber has a small amount of intermittent bubbling. This is most likely caused by:', '["A large air leak", "The patient''s respirations", "A kink in the tubing", "A blockage in the drainage system"]'::jsonb, 1, 'Intermittent bubbling in the water-seal chamber is a normal finding when the patient has an air leak. The bubbling occurs as the patient exhales and air is pushed out of the pleural space. It would not be caused by a large air leak or a blockage.', 'Respiratory', '🫁'),
(92, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is monitoring the drainage from a UWSD. The nurse should mark the drainage level on the collection chamber at least:', '["Once every 24 hours", "Once a shift", "Once an hour", "Only if the drainage is bloody"]'::jsonb, 1, 'Drainage should be monitored and marked at least once per shift to accurately track the amount of drainage. More frequent monitoring may be required, depending on the patient''s condition.', 'Respiratory', '🫁'),
(93, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse finds the UWSD system on the floor, and the water-seal is broken. The most appropriate initial action is to:', '["Clamp the chest tube and call the physician", "Immediately replace the UWSD system", "Submerge the chest tube''s end in a bottle of sterile water", "Cover the chest tube with a sterile dressing"]'::jsonb, 2, 'If the water seal is broken, the chest tube should immediately be placed in a container of sterile water to re-establish the water seal and prevent air from entering the chest cavity. The system should then be replaced as soon as possible.', 'Respiratory', '🫁'),
(94, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'What is the normal finding in the water-seal chamber of a UWSD system for a patient with a resolved pneumothorax?', '["Continuous bubbling", "No bubbling and no tidaling", "Continuous tidaling with no bubbling", "Intermittent bubbling"]'::jsonb, 1, 'When a pneumothorax has resolved, there should be no more air leaking from the lung. Therefore, there should be no bubbling in the water-seal chamber. The absence of tidaling indicates that the lung is fully re-expanded and no longer has negative pressure on it.', 'Respiratory', '🫁'),
(95, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is preparing to ambulate a patient with a chest tube and a UWSD. The nurse should:', '["Clamp the chest tube for the duration of the walk", "Disconnect the chest tube from the UWSD system", "Disconnect the UWSD system from the suction", "Ensure the UWSD system remains upright and below the chest level"]'::jsonb, 3, 'The UWSD system must remain upright to maintain the water seal and below the patient''s chest to use gravity for drainage. Clamping or disconnecting the system is unsafe and should not be done during ambulation.', 'Respiratory', '🫁'),
(96, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is teaching a new nurse about the UWSD system. The nurse should explain that the purpose of the suction control chamber is to:', '["Control the amount of drainage", "Create a water seal", "Apply a controlled amount of negative pressure", "Collect the drainage"]'::jsonb, 2, 'The suction control chamber, whether a wet or dry system, regulates the amount of negative pressure applied to the chest cavity. This helps to promote the drainage of air and fluid.', 'Respiratory', '🫁'),
(97, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is assessing a patient with a UWSD system. The patient has a severe tension pneumothorax. The nurse should expect to see:', '["A mediastinal shift and tracheal deviation to the affected side", "A mediastinal shift and tracheal deviation to the unaffected side", "Clear lung sounds on both sides", "An increase in blood pressure"]'::jsonb, 1, 'A tension pneumothorax is a medical emergency where air pressure in the chest cavity builds up and compresses the lung, heart, and great vessels. This pushes the trachea and the mediastinum to the opposite side (unaffected side), which is a key clinical sign.', 'Respiratory', '🫁'),
(98, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is preparing to assist with the removal of a chest tube. The nurse should have which of the following supplies readily available?', '["A sterile scalpel and sutures", "A chest tube insertion kit", "A sterile occlusive dressing and petroleum gauze", "A new UWSD system"]'::jsonb, 2, 'After the chest tube is removed, the insertion site is immediately covered with a sterile occlusive dressing and petroleum gauze to prevent air from entering the chest cavity. The physician will remove the tube, so the other options are not the nurse''s primary responsibility.', 'Respiratory', '🫁'),
(99, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient with a hemothorax. What is the most appropriate action if the patient''s chest tube drainage decreases significantly and the patient''s condition worsens?', '["Clamp the chest tube to prevent further drainage", "Notify the physician immediately", "Milk the tubing to dislodge the clot", "Increase the suction to the UWSD system"]'::jsonb, 1, 'A sudden decrease in drainage, coupled with a worsening patient condition, suggests that the chest tube may be occluded, leading to the re-accumulation of fluid in the chest. This is a medical emergency, and the physician must be notified immediately. Milking the tubing is generally discouraged as it can cause negative pressure damage to the lung tissue.', 'Respiratory', '🫁'),
(100, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient is receiving oxygen via a nasal cannula at a flow rate of 5 L/min. What is the approximate FiO₂ being delivered?', '["24%", "32%", "40%", "60%"]'::jsonb, 2, 'Room air is 21% FiO₂. For every 1 L/min of oxygen via a nasal cannula, the FiO₂ increases by approximately 4%. At 5 L/min, the calculation is 21\% + (5 \times 4\%) = 41\%, which is approximated to 40%.', 'Respiratory', '🫁'),
(101, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following is a crucial precaution a nurse must take when administering oxygen therapy?', '["Ensure the patient''s hands and face are moisturized with petroleum-based products.", "Place ''No Smoking'' signs in the patient''s room and surrounding area.", "Allow the oxygen tank to be placed on its side to conserve space.", "Avoid humidification to prevent the growth of bacteria in the water."]'::jsonb, 1, 'Oxygen is a highly combustible gas that accelerates burning, so fire safety precautions such as ''No Smoking'' signs are essential. Petroleum-based products are flammable, and tanks must be kept upright and secured. Humidification is necessary to prevent drying of mucous membranes.', 'Respiratory', '🫁'),
(102, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient requires a low, consistent concentration of oxygen. The most appropriate oxygen delivery device for this purpose is a:', '["Non-rebreather mask", "Nasal cannula", "Simple face mask", "Venturi mask"]'::jsonb, 3, 'A Venturi mask is a high-flow system that delivers a precise and consistent concentration of oxygen, regardless of the patient''s breathing pattern. The FiO₂ can be adjusted by changing the adapter.', 'Respiratory', '🫁'),
(103, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is caring for a patient on oxygen therapy. Which of the following is an early sign of oxygen toxicity?', '["Bradypnea", "Sudden increase in blood pressure", "Nonproductive cough and substernal chest pain", "Increased appetite"]'::jsonb, 2, 'Oxygen toxicity is caused by prolonged exposure to high concentrations of oxygen. Early signs include a nonproductive cough, substernal chest pain, and nasal stiffness.', 'Respiratory', '🫁'),
(104, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is humidifying oxygen for a patient. The purpose of humidification is to:', '["Increase the FiO₂ being delivered", "Prevent the growth of bacteria in the oxygen tubing", "Prevent drying of the patient''s mucous membranes", "Decrease the risk of oxygen toxicity"]'::jsonb, 2, 'Humidification adds moisture to the oxygen, which helps to prevent the drying of the nasal and oral mucosa. This is especially important for patients receiving high-flow oxygen or prolonged oxygen therapy.', 'Respiratory', '🫁'),
(105, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient is receiving oxygen via a non-rebreather mask. The nurse notices the reservoir bag is completely deflating with each inspiration. The most appropriate nursing action is to:', '["Increase the oxygen flow rate to the mask", "Replace the mask with a simple face mask", "Clamp the oxygen tubing", "Loosen the mask to allow more room air to enter"]'::jsonb, 0, 'The reservoir bag of a non-rebreather mask should remain inflated on both inspiration and expiration to ensure a high FiO₂ is delivered. If it is deflating, the flow rate is too low and should be increased to maintain a high concentration of oxygen.', 'Respiratory', '🫁'),
(106, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following patients is most likely to be weaned from oxygen therapy?', '["A patient with a chronic obstructive pulmonary disease (COPD) exacerbation", "A patient with a PaO₂ of 95 mmHg on a nasal cannula at 2 L/min", "A patient with a PaO₂ of 60 mmHg on a non-rebreather mask", "A patient with a SpO₂ of 88% on room air"]'::jsonb, 1, 'Weaning from oxygen therapy is a gradual process. A PaO₂ of 95 mmHg is well within the normal range, indicating that the patient is maintaining adequate oxygenation on a low-flow oxygen setting and may be ready to be weaned or have their oxygen discontinued.', 'Respiratory', '🫁'),
(107, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is administering oxygen to a patient with a history of COPD. The nurse should use caution with high-flow oxygen because it can:', '["Cause a sudden increase in the patient''s respiratory rate", "Lead to a decrease in the patient''s respiratory drive", "Cause a decrease in the patient''s blood pressure", "Lead to hypoxemia"]'::jsonb, 1, 'In some patients with COPD, the primary stimulus to breathe is a low PaO₂. Administering high-flow oxygen can remove this stimulus, leading to a decrease in the patient''s respiratory drive and hypoventilation.', 'Respiratory', '🫁'),
(108, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is educating a patient''s family about fire safety with oxygen. Which of the following is the most important piece of information to convey?', '["The oxygen tank is not a fire risk unless it is leaking", "Oxygen is a flammable gas", "Oxygen should not be used near open flames or heat sources", "The patient can smoke if they are more than 10 feet away from the oxygen tank"]'::jsonb, 2, 'Oxygen is not flammable itself, but it is a powerful oxidizer that can make a fire start more easily and burn more intensely. It should never be used near open flames, heaters, or any heat source.', 'Respiratory', '🫁'),
(109, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is assessing a patient receiving oxygen therapy via a simple face mask. The nurse knows that the minimum flow rate for this mask is:', '["1-2 L/min", "3-4 L/min", "5-6 L/min", "10-15 L/min"]'::jsonb, 2, 'The minimum flow rate for a simple face mask is 5 to 6 L/min. This is to ensure that the patient''s exhaled carbon dioxide is flushed from the mask. If the flow rate is too low, the patient could re-breathe their own CO₂, leading to hypercapnia.', 'Respiratory', '🫁'),
(110, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is monitoring a patient''s oxygen saturation with a pulse oximeter. A reading of 92% is considered:', '["Normal", "Mild hypoxemia", "Severe hypoxemia", "A sign of hyperoxia"]'::jsonb, 1, 'A normal oxygen saturation is typically 95% or higher. A reading of 92% is considered mild hypoxemia and may require an increase in oxygen therapy or further assessment.', 'Respiratory', '🫁'),
(111, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is caring for a patient who is post-operative and has hypoxemia. The nurse is ordered to apply a Venturi mask at 40%. The nurse should:', '["Adjust the oxygen flow rate to 10 L/min", "Ensure the correct color-coded Venturi adapter is attached to the mask", "Instruct the patient to keep the mask loose on their face", "Tell the patient to breathe through their nose only"]'::jsonb, 1, 'A Venturi mask uses color-coded adapters, each corresponding to a specific oxygen concentration and flow rate. The nurse must select the correct adapter for 40% FiO₂ to ensure the precise oxygen concentration is delivered to the patient.', 'Respiratory', '🫁'),
(112, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient on oxygen therapy complains of a dry nose and throat. The nurse should:', '["Discontinue the oxygen therapy", "Increase the oxygen flow rate", "Add a humidifier to the oxygen system", "Switch the patient to a non-rebreather mask"]'::jsonb, 2, 'Dryness of the mucous membranes is a common side effect of oxygen therapy, particularly when the oxygen is not humidified. Adding a humidifier to the oxygen system will help to alleviate this symptom.', 'Respiratory', '🫁'),
(113, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is monitoring a patient on oxygen therapy. Which of the following is an expected sign of improved oxygenation?', '["Increased restlessness and anxiety", "Cyanosis of the lips and fingertips", "A decrease in respiratory rate and a stable heart rate", "A decrease in blood pressure"]'::jsonb, 2, 'As oxygenation improves, the body no longer has to work as hard to compensate for the lack of oxygen. This leads to a decrease in the respiratory rate and a stable heart rate. The other signs are indicators of worsening hypoxemia.', 'Respiratory', '🫁'),
(114, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is weaning a patient from oxygen therapy. The most important parameter to monitor during this process is the patient''s:', '["Body temperature", "Blood pressure", "Oxygen saturation and respiratory status", "Pain level"]'::jsonb, 2, 'The primary goal of weaning is to ensure the patient can maintain adequate oxygenation without supplemental oxygen. The nurse must closely monitor the patient''s oxygen saturation and respiratory rate, effort, and rhythm for any signs of respiratory distress.', 'Respiratory', '🫁'),
(115, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient on oxygen therapy has a nasal cannula in place. The nurse should ensure that the tubing is:', '["Taped securely to the patient''s nose", "Placed in the patient''s mouth for better absorption", "Secured behind the patient''s ears and under the chin to prevent pressure injury", "Loosely coiled on the bed"]'::jsonb, 2, 'The tubing from a nasal cannula can cause pressure injuries on the skin behind the ears or on the face. Securing the tubing properly and using padding can help to prevent this complication.', 'Respiratory', '🫁'),
(116, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient who is hypoxic. The nurse should prioritize which of the following interventions?', '["Administering a sedative to calm the patient", "Increasing the oxygen flow rate as ordered", "Calling a respiratory therapist", "Placing the patient in a prone position"]'::jsonb, 1, 'For a hypoxic patient, the priority is to correct the hypoxemia. The nurse should first implement the ordered oxygen therapy, which involves increasing the flow rate. The other actions may be necessary, but this is the most immediate intervention to improve oxygenation.', 'Respiratory', '🫁'),
(117, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following patients is a candidate for a non-rebreather mask?', '["A patient with mild anxiety", "A patient who requires a low, consistent FiO₂", "A patient with severe hypoxemia requiring a high FiO₂", "A patient with chronic respiratory failure"]'::jsonb, 2, 'A non-rebreather mask is a high-flow system that can deliver up to 90-100% FiO₂, making it ideal for patients who have severe hypoxemia and require the highest possible concentration of oxygen short of intubation.', 'Respiratory', '🫁'),
(118, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is preparing to administer oxygen to a patient from a portable oxygen tank. The nurse knows that the most important first step is to:', '["Attach the humidifier", "Check the oxygen level in the tank", "Put the mask on the patient", "Turn on the flow meter"]'::jsonb, 1, 'The nurse must first check the oxygen level in the tank to ensure there is enough oxygen to last for the duration of the patient''s needs. Running out of oxygen during transport or a procedure can be a life-threatening situation.', 'Respiratory', '🫁'),
(119, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient on oxygen therapy is complaining of a headache and confusion. These symptoms may be an early sign of:', '["Oxygen toxicity", "Oxygen dependency", "Hypercapnia (high CO₂)", "Hypoglycemia"]'::jsonb, 2, 'Headache and confusion are classic signs of hypercapnia. This can occur in patients with COPD who are receiving high-flow oxygen, as it can suppress their respiratory drive, leading to a buildup of carbon dioxide in the blood.', 'Respiratory', '🫁'),
(120, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient is experiencing respiratory failure. Arterial Blood Gas (ABG) results show a PaO₂ of 55 mmHg. Which type of respiratory failure is this most likely to be?', '["Type I (Hypoxemic) Respiratory Failure", "Type II (Hypercapnic) Respiratory Failure", "Mixed Respiratory Failure", "There is not enough information to determine the type"]'::jsonb, 0, 'Type I respiratory failure is defined by a low PaO₂ (typically below 60 mmHg) with a normal or low PaCO₂. The provided value of 55 mmHg falls within the range for Type I respiratory failure.', 'Respiratory', '🫁'),
(121, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'In a patient with respiratory failure, the nurse correctly interprets a high PaCO₂ value and a low pH from an ABG. This indicates:', '["Metabolic alkalosis", "Respiratory alkalosis", "Metabolic acidosis", "Respiratory acidosis"]'::jsonb, 3, 'A high PaCO₂ indicates hypoventilation, which causes a buildup of carbonic acid and results in a low pH, a classic sign of respiratory acidosis. This is a ventilation problem, not a metabolic one.', 'Respiratory', '🫁'),
(122, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is assessing a patient for signs of respiratory failure. Which of the following is an early sign of hypoxemia?', '["Cyanosis", "Bradycardia", "Restlessness and confusion", "A decrease in respiratory rate"]'::jsonb, 2, 'Early signs of hypoxemia are often neurological, as the brain is very sensitive to a lack of oxygen. The patient may appear restless, confused, or anxious. Cyanosis is a late sign of hypoxemia, and bradycardia is a very late sign.', 'Respiratory', '🫁'),
(123, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is caring for a patient with Type II respiratory failure. The primary cause of this type of respiratory failure is:', '["A problem with oxygenation and diffusion", "A problem with ventilation and CO₂ removal", "An issue with fluid volume overload", "A cardiac event"]'::jsonb, 1, 'Type II (hypercapnic) respiratory failure is caused by an inability to remove carbon dioxide, leading to a buildup of PaCO₂. This is a ventilation issue, where the lungs cannot properly expel gas, unlike Type I, which is a diffusion or oxygenation problem.', 'Respiratory', '🫁'),
(124, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient with respiratory failure is receiving oxygenation and ventilation support. The nurse knows that the main goal of this therapy is to:', '["Keep the patient asleep and comfortable", "Reduce the workload of the heart", "Reverse the underlying cause of the respiratory failure", "Maintain adequate gas exchange and support vital organ function"]'::jsonb, 3, 'The primary goal of respiratory support is to ensure that the patient is receiving enough oxygen to meet their metabolic needs and that carbon dioxide is being adequately removed, thus maintaining gas exchange and preventing organ damage.', 'Respiratory', '🫁'),
(125, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is interpreting an ABG for a patient. The results are pH 7.28, PaCO₂ 60 mmHg, and HCO₃⁻ 24 mEq/L. This indicates:', '["Compensated metabolic acidosis", "Uncompensated respiratory acidosis", "Partially compensated respiratory alkalosis", "Uncompensated respiratory alkalosis"]'::jsonb, 1, 'The low pH (< 7.35) indicates acidosis. The high PaCO₂ (> 45 mmHg) indicates a respiratory cause. The normal bicarbonate (HCO_{3}^{-}) level indicates that the kidneys have not had time to compensate. Therefore, the patient has uncompensated respiratory acidosis.', 'Respiratory', '🫁'),
(126, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is caring for a patient with respiratory failure and notes that the patient''s respiratory rate is 4 breaths per minute. The most appropriate action is to:', '["Wait for the patient''s breathing to improve", "Administer a sedative to the patient", "Immediately initiate bag-mask ventilation and call for help", "Administer more oxygen via a nasal cannula"]'::jsonb, 2, 'A respiratory rate of 4 breaths per minute is a life-threatening emergency, indicating severe hypoventilation. The nurse must immediately initiate bag-mask ventilation to provide breaths to the patient and call for a rapid response or code team.', 'Respiratory', '🫁'),
(127, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient is on a ventilator for respiratory failure. The nurse knows that a high pressure alarm on the ventilator may indicate:', '["A leak in the circuit", "The patient is disconnected from the ventilator", "A kinked endotracheal tube or the patient is coughing", "The patient''s lung has re-expanded"]'::jsonb, 2, 'A high pressure alarm indicates an obstruction in the ventilator circuit. This can be caused by a kinked tube, a buildup of secretions, or the patient coughing, biting the tube, or fighting the ventilator.', 'Respiratory', '🫁'),
(128, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient with respiratory failure has a PaO₂ of 45 mmHg despite receiving oxygen via a non-rebreather mask. The nurse anticipates that the next step in the patient''s care will be:', '["Weaning the patient from oxygen", "Transferring the patient to a regular medical floor", "Intubation and mechanical ventilation", "Increasing the oxygen flow rate to 15 L/min"]'::jsonb, 2, 'A PaO₂ of 45 mmHg on a non-rebreather mask indicates a severe oxygenation failure that is not responding to non-invasive support. The next step is typically to secure the airway with an endotracheal tube and initiate mechanical ventilation to provide more effective oxygenation and ventilation.', 'Respiratory', '🫁'),
(129, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is assessing a patient with a known history of COPD. The nurse should be aware that the patient is at risk for Type II respiratory failure due to:', '["An increase in gas exchange efficiency", "A decrease in lung compliance", "Chronic carbon dioxide retention", "A hyperactive respiratory drive"]'::jsonb, 2, 'Many patients with COPD have chronically elevated PaCO₂ levels, making them susceptible to Type II respiratory failure. Their respiratory system has become less responsive to high CO₂ levels, and a further increase can lead to hypoventilation and acidosis.', 'Respiratory', '🫁'),
(130, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is caring for a patient with respiratory failure. The nurse should prioritize which of the following positions to improve oxygenation?', '["The Trendelenburg position", "A flat, supine position", "A semi-Fowler''s or high-Fowler''s position", "A prone position with the head rotated to the side"]'::jsonb, 2, 'A semi-Fowler''s or high-Fowler''s position allows for the maximum expansion of the lungs, making it easier for the patient to breathe and improving gas exchange. The other positions can impede lung expansion and should be avoided.', 'Respiratory', '🫁'),
(131, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is interpreting ABG results for a patient with respiratory failure. The nurse knows that a normal pH range is:', '["7.45 - 7.55", "7.35 - 7.45", "7.25 - 7.35", "7.15 - 7.25"]'::jsonb, 1, 'The normal pH range for arterial blood is 7.35 - 7.45. A pH below this range indicates acidosis, and a pH above this range indicates alkalosis.', 'Respiratory', '🫁'),
(132, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is caring for a patient with acute respiratory distress syndrome (ARDS). The nurse knows that ARDS is a common cause of:', '["Type II respiratory failure", "Hypoxemic (Type I) respiratory failure", "Metabolic acidosis", "Respiratory alkalosis"]'::jsonb, 1, 'ARDS is a severe form of acute lung injury that leads to widespread inflammation and fluid accumulation in the lungs. This impairs oxygenation, making it a classic cause of Type I respiratory failure.', 'Respiratory', '🫁'),
(133, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is managing a patient with respiratory failure who is on a ventilator. The nurse should be aware that the risk of ventilator-associated pneumonia (VAP) can be reduced by:', '["Keeping the head of the bed flat", "Performing frequent oral care with a chlorhexidine rinse", "Administering a large dose of sedatives", "Increasing the tidal volume on the ventilator"]'::jsonb, 1, 'VAP is a serious complication of mechanical ventilation. One of the key interventions to prevent VAP is to perform frequent oral care, often with a chlorhexidine rinse, to reduce the bacterial load in the mouth that can be aspirated into the lungs.', 'Respiratory', '🫁'),
(134, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient with respiratory failure is being monitored for signs of hypercapnia. Which of the following is a late sign of hypercapnia?', '["Restlessness", "Drowsiness and lethargy", "Tachypnea", "Anxiety"]'::jsonb, 1, 'As CO₂ levels rise, the patient''s level of consciousness can decline. Drowsiness, lethargy, and a decreased level of consciousness are late signs of severe hypercapnia and can progress to a coma.', 'Respiratory', '🫁'),
(135, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is caring for a patient with Type I respiratory failure due to pneumonia. The nurse knows that the underlying problem is:', '["The patient''s inability to exhale air from their lungs", "A decrease in gas exchange due to fluid and inflammation in the alveoli", "The patient''s airway is completely obstructed", "The patient has an inadequate respiratory drive"]'::jsonb, 1, 'Pneumonia causes inflammation and fluid buildup in the alveoli, which impairs the diffusion of oxygen into the bloodstream. This is a classic cause of Type I respiratory failure, which is a problem with oxygenation.', 'Respiratory', '🫁'),
(136, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is educating a patient''s family about the cause of Type I respiratory failure. The nurse should explain that it is caused by:', '["A failure of the respiratory muscles", "A ventilation defect", "A problem with oxygen transfer across the alveolar-capillary membrane", "An issue with the central nervous system"]'::jsonb, 2, 'Type I respiratory failure is a failure of oxygenation. This occurs when there is a problem with the transfer of oxygen from the alveoli to the bloodstream across the alveolar-capillary membrane, which can be caused by conditions like pneumonia or pulmonary edema.', 'Respiratory', '🫁'),
(137, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient is on a ventilator and the nurse notes a low pressure alarm. The most likely cause is:', '["A kink in the tubing", "The patient is biting the endotracheal tube", "A disconnection in the ventilator circuit", "The patient is coughing"]'::jsonb, 2, 'A low pressure alarm indicates a leak or a disconnection in the ventilator circuit. This means that the ventilator is not able to deliver the required pressure to the patient''s lungs. Kinking, biting, or coughing would cause a high pressure alarm.', 'Respiratory', '🫁'),
(138, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is assessing a patient with respiratory failure. The nurse notes that the patient''s respiratory rate is 35 breaths per minute. This is an example of:', '["Eupnea", "Bradypnea", "Tachypnea", "Apnea"]'::jsonb, 2, 'Tachypnea is an abnormally rapid respiratory rate, typically defined as more than 20 breaths per minute. The patient is breathing fast to compensate for the respiratory failure and try to improve gas exchange.', 'Respiratory', '🫁'),
(139, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is interpreting ABG results for a patient and notes a normal PaO₂ and a high PaCO₂. This is an example of:', '["Normal findings", "Uncompensated respiratory acidosis", "Uncompensated respiratory alkalosis", "Uncompensated metabolic acidosis"]'::jsonb, 1, 'A normal PaO₂ and a high PaCO₂ indicate that the patient is able to oxygenate but is not able to ventilate effectively. The high PaCO₂ causes respiratory acidosis. If the pH is low and the HCO₃⁻ is normal, it is uncompensated.', 'Respiratory', '🫁'),
(140, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'According to the Parkland formula, how much fluid is a nurse required to administer to a patient weighing 70 kg with 30% total body surface area (TBSA) burns in the first 8 hours?', '["4200 mL", "8400 mL", "2100 mL", "2800 mL"]'::jsonb, 0, 'The Parkland formula is 4 mL x kg x %TBSA. For this patient, the total fluid needed in 24 hours is 4 \\times 70 \\times 30 = 8400 mL. Half of this amount, 4200 mL, is administered in the first 8 hours.', 'Burns & Trauma', '🔥'),
(141, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient has a full-thickness burn. The nurse would expect to see which of the following characteristics?', '["Pain, redness, and blisters", "Charred appearance, eschar, and no sensation to touch", "Blanching with pressure and swelling", "Minimal redness and dry, flaky skin"]'::jsonb, 1, 'Full-thickness burns destroy the entire dermis and nerve endings, resulting in a leathery, waxy appearance and a lack of pain sensation in the burned area. The other options describe less severe burns.', 'Burns & Trauma', '🔥'),
(142, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is performing initial emergency care for a burn patient. The first priority is to:', '["Administer pain medication", "Start fluid resuscitation", "Stop the burning process", "Cover the burned area with a dry sterile dressing"]'::jsonb, 2, 'The first priority in burn management is to stop the burning process. This can be done by removing the patient from the source of the burn, extinguishing flames, and dousing the area with cool water. This prevents further tissue damage.', 'Burns & Trauma', '🔥'),
(143, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient has a partial-thickness (second-degree) burn. The nurse should expect to see:', '["Only redness and mild pain", "White, charred, and painless skin", "Blisters, weeping skin, and severe pain", "Dry, leathery skin with no sensation"]'::jsonb, 2, 'A partial-thickness burn affects the epidermis and part of the dermis. It is characterized by blisters, weeping or moist skin, and severe pain, as the nerve endings are still intact and exposed.', 'Burns & Trauma', '🔥'),
(144, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is providing wound care for a patient with a burn. The main goal of burn wound care is to:', '["Promote the formation of eschar", "Keep the wound wet to prevent infection", "Prevent infection and promote healing", "Only use topical antibiotics"]'::jsonb, 2, 'The primary goals of burn wound care are to prevent infection, which is a major complication, and to create an optimal environment for wound healing. This often involves cleaning the wound, debriding dead tissue, and applying dressings with or without topical antimicrobial agents.', 'Burns & Trauma', '🔥'),
(145, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient with a severe burn is at high risk for which of the following complications in the first 24 hours?', '["Fluid volume excess", "Hyperglycemia", "Hypovolemic shock", "Hypertension"]'::jsonb, 2, 'In the initial stages of a severe burn, there is a massive fluid shift from the intravascular space to the interstitial space. This can lead to a significant drop in blood volume and can cause hypovolemic shock if not treated promptly with fluid resuscitation.', 'Burns & Trauma', '🔥'),
(146, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is administering fluids to a burn patient according to the Parkland formula. The nurse should know that the fluid of choice is:', '["Dextrose in water", "0.9% Normal Saline", "Lactated Ringer''s solution", "Albumin"]'::jsonb, 2, 'Lactated Ringer''s solution is the fluid of choice for burn resuscitation because its electrolyte composition is very similar to that of human plasma. It helps to correct the fluid volume deficit without causing significant electrolyte imbalances.', 'Burns & Trauma', '🔥'),
(147, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient with a major burn is receiving pain management. The nurse should be aware that which of the following routes is most appropriate for pain medication?', '["Oral medications", "Intramuscular injections", "Subcutaneous injections", "Intravenous (IV) medications"]'::jsonb, 3, 'Intramuscular and subcutaneous injections are generally avoided in burn patients due to poor absorption in the burned tissue. Oral medications are also not reliable due to potential GI issues. IV administration is the most reliable and fastest way to provide pain relief.', 'Burns & Trauma', '🔥'),
(148, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is assessing a burn patient for signs of an inhalation injury. Which of the following is a key sign of a potential inhalation injury?', '["A small burn on the hand", "Burned facial hair, soot in the nares or mouth, and a hoarse voice", "A normal respiratory rate", "Clear breath sounds"]'::jsonb, 1, 'Inhalation injury is a serious complication of burns and can be difficult to assess. Key signs include burned facial hair, soot in the oral or nasal passages, and a change in the patient''s voice, all of which indicate damage to the upper airway.', 'Burns & Trauma', '🔥'),
(149, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is providing psychological support to a burn patient. The nurse should be aware that the patient may experience which of the following emotional responses?', '["A sense of euphoria", "Apathy and indifference", "Anxiety, depression, and body image disturbance", "A rapid return to normal daily life"]'::jsonb, 2, 'Burn patients often experience significant psychological trauma. They may struggle with anxiety, depression, post-traumatic stress disorder (PTSD), and body image disturbance due to the disfigurement caused by the burns. The nurse''s role is to provide compassionate care and support.', 'Burns & Trauma', '🔥'),
(150, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient with a severe burn is being monitored for signs of compartment syndrome. The nurse should assess for which of the following?', '["A sudden drop in blood pressure", "A decrease in pain", "A sudden loss of distal pulses and increased pain", "An increase in urine output"]'::jsonb, 2, 'Compartment syndrome is a surgical emergency that can occur in patients with circumferential burns. The eschar acts as a tourniquet, leading to an increase in pressure that compresses nerves and blood vessels. This results in severe pain, loss of pulses, and numbness.', 'Burns & Trauma', '🔥'),
(151, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient with a burn and notes that the patient''s urine output is low. The nurse should know that this is most likely caused by:', '["A problem with the kidneys", "The body''s normal response to fluid resuscitation", "A significant fluid shift and decreased renal perfusion", "The patient''s refusal to drink"]'::jsonb, 2, 'In the initial burn phase, a significant amount of fluid shifts from the intravascular space. This leads to decreased cardiac output and renal perfusion, which results in a low urine output. Aggressive fluid resuscitation is needed to correct this.', 'Burns & Trauma', '🔥'),
(152, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient with a large burn is being monitored for infection. The nurse should be aware that the primary source of infection in a burn patient is:', '["The patient''s own skin flora", "The hospital environment", "The patient''s visitors", "The burn wound itself"]'::jsonb, 3, 'The burn wound itself is a perfect medium for bacterial growth. It is a large, open area of tissue that is susceptible to colonization by bacteria. The nurse must use strict aseptic technique and proper wound care to prevent infection.', 'Burns & Trauma', '🔥'),
(153, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is teaching a family about the classification of burns. A third-degree burn is also known as a:', '["Superficial burn", "Partial-thickness burn", "Full-thickness burn", "Superficial partial-thickness burn"]'::jsonb, 2, 'A third-degree burn is a full-thickness burn, meaning it extends through all layers of the skin, destroying the epidermis, dermis, and often the underlying fat, muscle, and bone.', 'Burns & Trauma', '🔥'),
(154, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is providing care for a patient with a burn on the hand. To prevent contractures, the nurse should:', '["Immobilize the hand in a position of comfort", "Elevate the hand and perform active and passive range-of-motion exercises", "Place the hand in a dependent position", "Keep the hand wrapped in a bulky dressing"]'::jsonb, 1, 'To prevent contractures, the nurse should elevate the hand to reduce swelling and perform frequent range-of-motion exercises. The hand should be splinted in a functional position to prevent the formation of a permanent contracture.', 'Burns & Trauma', '🔥'),
(155, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient with a burn and notes that the patient''s blood pressure is low and their heart rate is high. This is an early sign of:', '["Fluid volume excess", "An infection", "Hypovolemic shock", "Compartment syndrome"]'::jsonb, 2, 'A low blood pressure and a high heart rate are classic signs of hypovolemic shock. This is caused by the massive fluid shift from the intravascular space to the interstitial space that occurs in the early stages of a severe burn.', 'Burns & Trauma', '🔥'),
(156, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is assessing the depth of a burn. A burn that is characterized by redness and pain but no blisters is a:', '["First-degree burn", "Second-degree burn", "Third-degree burn", "Fourth-degree burn"]'::jsonb, 0, 'A first-degree burn, or superficial burn, only affects the epidermis. It is characterized by redness, pain, and dry skin, similar to a sunburn. It does not cause blistering and heals on its own.', 'Burns & Trauma', '🔥'),
(157, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is providing care for a patient with a burn on their chest. The nurse should be aware that the patient is at risk for which of the following?', '["Cardiac arrhythmias", "Respiratory complications", "Kidney failure", "Liver failure"]'::jsonb, 1, 'A burn on the chest can cause swelling and constriction of the chest wall, which can impede breathing and lead to respiratory complications. Inhalation injury is also a major concern for patients with facial or upper body burns.', 'Burns & Trauma', '🔥'),
(158, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient with a burn and notes that the patient''s urine is dark brown. The nurse should suspect which of the following?', '["A urinary tract infection", "A decrease in fluid intake", "Rhabdomyolysis", "A normal finding"]'::jsonb, 2, 'Rhabdomyolysis is the breakdown of muscle tissue, which can release myoglobin into the bloodstream. This can cause the urine to turn dark brown and can lead to acute kidney injury. This is a serious complication of severe burns, particularly electrical burns.', 'Burns & Trauma', '🔥'),
(159, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is providing wound care for a patient with a burn. The nurse should use which of the following to clean the wound?', '["Alcohol", "Hydrogen peroxide", "A mild, non-irritating cleanser and water", "A strong antiseptic solution"]'::jsonb, 2, 'The burn wound should be cleaned with a mild, non-irritating cleanser and water. Strong antiseptics and alcohol can be harmful to the delicate new tissue and should be avoided. The goal is to gently remove any debris and dead tissue.', 'Burns & Trauma', '🔥'),
(160, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'What is the correct sequence of steps for neonatal resuscitation (NALS)?', '["Ventilation, Chest Compressions, Suctioning, Warmth", "Airway, Breathing, Circulation, Drugs", "Warmth, Position, Suction, Dry, Stimulate", "Oxygen, Chest Compressions, Intubation, Medications"]'::jsonb, 2, 'The initial steps of neonatal resuscitation, known as the "A-B-C" of the newborn, focus on providing a supportive environment and ensuring a patent airway. The sequence is to provide warmth, position the airway, suction secretions if needed, dry the newborn, and provide tactile stimulation.', 'Obstetric & Neonatal', '🤱'),
(161, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A newborn is born with poor muscle tone and is not breathing. The nurse''s first action, after ensuring warmth and position, should be:', '["To administer chest compressions", "To intubate the newborn", "To provide positive-pressure ventilation", "To administer epinephrine"]'::jsonb, 2, 'For an apneic or gasping newborn, positive-pressure ventilation is the most effective step after initial airway management and stimulation. Chest compressions and medications are only initiated if the heart rate remains low despite effective ventilation.', 'Obstetric & Neonatal', '🤱'),
(162, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is assessing a newborn for signs of birth asphyxia. Which of the following is a key sign?', '["A pink color and a strong cry", "A heart rate of 120 beats per minute", "Poor muscle tone and a low Apgar score", "A vigorous kick and a respiratory rate of 40 breaths per minute"]'::jsonb, 2, 'Birth asphyxia is a condition where a newborn experiences a lack of oxygen. Key signs include poor muscle tone, a weak or absent cry, and a low Apgar score (less than 7 at 5 minutes), all of which indicate poor respiratory and neurological status.', 'Obstetric & Neonatal', '🤱'),
(163, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a newborn in the NICU and suspects neonatal sepsis. Which of the following is an early sign of neonatal sepsis?', '["A high-grade fever", "A stable blood sugar level", "A sudden increase in activity", "Poor feeding, lethargy, and respiratory distress"]'::jsonb, 3, 'Neonatal sepsis can be difficult to detect, as newborns do not always have a fever. Early signs include subtle changes in behavior, such as poor feeding, lethargy, a "floppy" appearance, and signs of respiratory distress like grunting or nasal flaring.', 'Obstetric & Neonatal', '🤱'),
(164, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is performing neonatal resuscitation. The newborn''s heart rate is below 60 beats per minute after 30 seconds of effective positive-pressure ventilation. The next step is to:', '["Continue positive-pressure ventilation for another 30 seconds", "Administer epinephrine", "Initiate chest compressions", "Stop resuscitation and call the physician"]'::jsonb, 2, 'According to NALS guidelines, if the heart rate remains below 60 beats per minute after 30 seconds of effective positive-pressure ventilation, the nurse should initiate chest compressions while continuing ventilation. Epinephrine is administered if the heart rate remains below 60 bpm after another 60 seconds of chest compressions and ventilation.', 'Obstetric & Neonatal', '🤱'),
(165, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is providing care for a newborn who is at risk for hypothermia. The most effective nursing intervention is to:', '["Place the newborn under a radiant warmer", "Bathe the newborn immediately after birth", "Keep the newborn''s crib away from any heat sources", "Wrap the newborn in a cold towel"]'::jsonb, 0, 'Placing the newborn under a radiant warmer is the most effective way to prevent and treat hypothermia. It provides a constant source of heat that helps to maintain the newborn''s body temperature. Bathing should be delayed until the temperature is stable.', 'Obstetric & Neonatal', '🤱'),
(166, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is providing family-centered NICU care. The primary goal of family-centered care is to:', '["Allow the parents to make all of the medical decisions", "Keep the parents separated from the newborn to prevent infection", "Involve the parents as partners in the newborn''s care", "Only communicate with the parents when they ask a question"]'::jsonb, 2, 'Family-centered care recognizes that the family is the constant in the newborn''s life. The goal is to involve the parents as partners in the newborn''s care, empowering them and providing them with the information and skills they need to care for their newborn after discharge.', 'Obstetric & Neonatal', '🤱'),
(167, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a newborn with birth asphyxia. The nurse knows that the main cause of birth asphyxia is:', '["A genetic condition", "A lack of oxygen to the newborn''s brain", "A bacterial infection", "A birth injury"]'::jsonb, 1, 'Birth asphyxia is caused by a lack of oxygen and blood flow to the brain and other organs around the time of birth. It can lead to a variety of short-term and long-term complications.', 'Obstetric & Neonatal', '🤱'),
(168, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'Which of the following is a key difference between sedation and anesthesia in critical care?', '["Sedation causes a complete loss of sensation and consciousness, while anesthesia only reduces anxiety.", "Anesthesia is typically administered via oral medications, while sedation is always given intravenously.", "Sedation allows for arousability and maintains protective airway reflexes, while anesthesia typically requires mechanical ventilation.", "Sedation is only used for short-term procedures, whereas anesthesia is used for prolonged surgeries."]'::jsonb, 2, 'Sedation aims to calm a patient, often leaving them arousable and with intact protective reflexes. Anesthesia, by contrast, renders the patient unconscious, which typically necessitates airway support and mechanical ventilation.', 'Anaesthesia & Perioperative Care', '💉'),
(169, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is monitoring a sedated patient in the ICU using the Richmond Agitation-Sedation Scale (RASS). A score of 0 on the RASS indicates:', '["Unarousable", "Agitated or restless", "Alert and calm", "Light sedation"]'::jsonb, 2, 'The RASS score ranges from -5 (unarousable) to +4 (combative). A score of 0 signifies a patient who is alert, calm, and able to interact appropriately. The other options correspond to different scores on the scale.', 'Anaesthesia & Perioperative Care', '💉'),
(170, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient in the ICU is receiving a continuous infusion of Propofol for sedation. The nurse should be aware that the patient is at risk for which of the following side effects?', '["Hyperglycemia and hypertension", "Hypotension and respiratory depression", "Hyperthermia and tachycardia", "Seizures"]'::jsonb, 1, 'Propofol is a potent sedative that has a strong cardiovascular effect. A common side effect is hypotension due to its vasodilation properties. It also has a powerful respiratory depressant effect, which is why patients receiving it often require mechanical ventilation.', 'Anaesthesia & Perioperative Care', '💉'),
(171, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is monitoring a sedated patient using the Bispectral Index (BIS) monitoring. The purpose of BIS monitoring is to:', '["Monitor the patient''s blood pressure", "Assess the patient''s heart rate", "Measure the patient''s level of consciousness", "Assess the patient''s muscle paralysis"]'::jsonb, 2, 'BIS monitoring uses a sensor on the patient''s forehead to measure brain activity. The BIS number provides a continuous assessment of the patient''s level of consciousness, helping to ensure the patient is not over- or under-sedated.', 'Anaesthesia & Perioperative Care', '💉'),
(172, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient who is post-anesthesia. The primary nursing responsibility in the post-anesthesia care unit (PACU) is to:', '["Administer a sedative to keep the patient asleep", "Monitor the patient''s vital signs and respiratory status", "Feed the patient a light meal", "Allow the patient to get up and walk around immediately"]'::jsonb, 1, 'In the PACU, the nurse''s priority is to monitor for complications from anesthesia, particularly respiratory depression and hypotension. The nurse must closely monitor the patient''s vital signs, level of consciousness, and respiratory status to ensure a safe recovery.', 'Anaesthesia & Perioperative Care', '💉'),
(173, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient is receiving Midazolam for sedation. The nurse knows that Midazolam is a:', '["Opioid analgesic", "Beta-blocker", "Benzodiazepine", "Neuromuscular blocking agent"]'::jsonb, 2, 'Midazolam is a benzodiazepine, which is a class of drugs that acts on the central nervous system to produce sedation and amnesia. It is commonly used for short-term sedation and anxiolysis.', 'Anaesthesia & Perioperative Care', '💉'),
(174, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is administering Ketamine to a patient for a procedural sedation. The nurse should be aware of which of the following side effects?', '["Bradycardia and hypotension", "Respiratory depression and hypothermia", "Hallucinations and increased salivation", "Hypoglycemia"]'::jsonb, 2, 'Ketamine is a dissociative anesthetic that can cause hallucinations and vivid dreams as the patient emerges from the sedation. It can also cause an increase in salivation, which requires the nurse to monitor for and manage secretions to prevent aspiration.', 'Anaesthesia & Perioperative Care', '💉'),
(175, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is caring for a patient on a continuous sedative infusion. The nurse should be aware that which of the following is a major complication of prolonged sedation?', '["Increased mobility and decreased risk of pressure ulcers", "An increased level of consciousness", "Delirium and an increased length of stay in the ICU", "A decreased need for mechanical ventilation"]'::jsonb, 2, 'Prolonged sedation can lead to a number of negative consequences, including delirium, an increased length of stay, and an increased risk of long-term cognitive impairment. The goal is to use the least amount of sedation necessary to keep the patient comfortable and safe.', 'Anaesthesia & Perioperative Care', '💉'),
(176, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient on a continuous sedative infusion. The nurse should titrate the sedative infusion based on:', '["The patient''s heart rate", "The patient''s blood pressure", "A validated sedation scale, such as RASS or a similar scale", "The nurse''s personal judgment"]'::jsonb, 2, 'Sedative infusions should be titrated based on an objective, validated scale. This helps to ensure that the patient is receiving the correct level of sedation to meet their needs without being over- or under-sedated, which can lead to complications.', 'Anaesthesia & Perioperative Care', '💉'),
(177, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient is on a neuromuscular blocking agent. The nurse knows that this medication is used to:', '["Relieve pain", "Induce sedation", "Cause muscle paralysis", "Decrease anxiety"]'::jsonb, 2, 'Neuromuscular blocking agents are used to paralyze the patient''s muscles. They do not have a sedative or analgesic effect. The patient may still be conscious and able to feel pain and anxiety, so they must be used in conjunction with a sedative and an analgesic.', 'Anaesthesia & Perioperative Care', '💉'),
(178, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient who is post-anesthesia. The patient is experiencing shivering. The nurse knows that shivering can:', '["Decrease the patient''s oxygen consumption", "Increase the patient''s metabolic rate and oxygen consumption", "Cause a decrease in the patient''s heart rate", "Indicate that the patient is too warm"]'::jsonb, 1, 'Shivering is a body''s response to hypothermia. It increases the patient''s metabolic rate and can significantly increase oxygen consumption, which can be dangerous for a patient who has just had surgery. The nurse should provide warmth to the patient to stop the shivering.', 'Anaesthesia & Perioperative Care', '💉'),
(179, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a sedated patient. The nurse should be aware that the patient is at risk for which of the following?', '["Decreased risk of aspiration", "An increased level of consciousness", "Pressure ulcers and skin breakdown", "A decrease in length of stay in the ICU"]'::jsonb, 2, 'A sedated patient has a decreased level of consciousness and may be immobile for prolonged periods. This makes them highly susceptible to pressure ulcers and skin breakdown. The nurse must perform frequent repositioning and skin assessments.', 'Anaesthesia & Perioperative Care', '💉'),
(180, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'The nurse is caring for a patient who is on a continuous infusion of Propofol. The nurse should be aware that the infusion should be changed every:', '["12 hours", "24 hours", "48 hours", "72 hours"]'::jsonb, 0, 'Propofol is a lipid-based medication, which makes it a perfect medium for bacterial growth. The infusion and tubing must be changed every 12 hours to reduce the risk of a bloodstream infection.', 'Anaesthesia & Perioperative Care', '💉'),
(181, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is managing the pain of a patient who is sedated. The nurse knows that the most effective way to assess a sedated patient''s pain is by:', '["Asking the patient to rate their pain on a scale of 1-10", "Assessing the patient''s heart rate and blood pressure", "Using a behavioral pain scale, such as the BPS or CPOT", "Assuming the patient is not in pain since they are sedated"]'::jsonb, 2, 'A sedated patient cannot verbally communicate their pain. The nurse must use a validated behavioral pain scale, such as the Behavioral Pain Scale (BPS) or the Critical-Care Pain Observation Tool (CPOT), which assesses non-verbal signs of pain like facial expressions and body movements.', 'Anaesthesia & Perioperative Care', '💉'),
(182, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is administering anesthesia to a patient. The nurse knows that the main goal of anesthesia is to:', '["Keep the patient awake during the procedure", "Provide a state of unconsciousness, muscle relaxation, and pain relief", "Increase the patient''s blood pressure", "Cause the patient to feel every sensation of the procedure"]'::jsonb, 1, 'Anesthesia is a state of controlled, temporary loss of sensation or awareness. The goal is to provide a combination of unconsciousness, muscle relaxation, and pain relief so that the patient can undergo a surgical procedure without feeling or remembering it.', 'Anaesthesia & Perioperative Care', '💉'),
(183, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient who is receiving sedation with Midazolam. The nurse should be aware that the patient is at risk for which of the following?', '["Hyperthermia", "Respiratory depression", "Hypotension", "Seizures"]'::jsonb, 1, 'All benzodiazepines, including Midazolam, can cause respiratory depression, especially in high doses or when combined with other sedatives. The nurse must closely monitor the patient''s respiratory rate and effort to ensure they are breathing adequately.', 'Anaesthesia & Perioperative Care', '💉'),
(184, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient who is on a continuous sedative infusion. The nurse should know that sedation holidays, where the infusion is turned off, are used to:', '["Save money on medication", "Assess the patient''s neurological status and readiness for extubation", "Increase the patient''s risk of delirium", "Ensure the patient is not in pain"]'::jsonb, 1, 'Sedation holidays are a critical part of ICU care. They involve temporarily discontinuing the sedative infusion to allow the patient to "wake up" so the nurse can assess their neurological status, cognitive function, and readiness to be weaned from the ventilator.', 'Anaesthesia & Perioperative Care', '💉'),
(185, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient who is sedated. The nurse should ensure that the patient''s dignity is maintained by:', '["Leaving the patient''s door open", "Talking about the patient''s condition with other staff members in front of them", "Providing privacy and explaining all care procedures to the patient, even if they are unresponsive", "Only providing care when the patient''s family is present"]'::jsonb, 2, 'Even if a patient is unresponsive, they may still be able to hear. The nurse should provide privacy, explain all care procedures in a respectful manner, and treat the patient as if they are conscious to maintain their dignity.', 'Anaesthesia & Perioperative Care', '💉'),
(186, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A patient is receiving a sedative with a continuous infusion. The nurse notes that the patient''s respiratory rate is 8 breaths per minute. The most appropriate action is to:', '["Increase the sedative infusion rate", "Continue to monitor the patient closely", "Stop the sedative infusion and administer Naloxone", "Stop the sedative infusion and stimulate the patient"]'::jsonb, 3, 'A respiratory rate of 8 breaths per minute is a sign of severe respiratory depression. The nurse should immediately stop the sedative infusion and stimulate the patient to encourage them to breathe. Naloxone is for opioid overdose, and the nurse should not increase the infusion rate.', 'Anaesthesia & Perioperative Care', '💉'),
(187, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient who is post-anesthesia. The patient is experiencing a sudden increase in heart rate. The nurse should suspect:', '["A normal recovery from anesthesia", "A complication such as pain, hypovolemia, or hypoxemia", "The patient is too cold", "The patient''s blood pressure is too high"]'::jsonb, 1, 'A sudden increase in heart rate (tachycardia) is not a normal finding post-anesthesia. It can be a sign of a number of complications, including pain, hypovolemia (low blood volume), or hypoxemia (low oxygen levels). The nurse should assess the patient and address the underlying cause.', 'Anaesthesia & Perioperative Care', '💉'),
(188, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient who is on a continuous sedative infusion. The nurse should be aware that the patient is at risk for which of the following?', '["A decrease in length of stay in the ICU", "An increased level of consciousness", "A lack of sleep and rest", "A tolerance to the sedative and a need for a higher dose"]'::jsonb, 3, 'Over time, patients can develop a tolerance to sedatives, which means they require a higher dose to achieve the same level of sedation. The nurse must be aware of this and titrate the infusion accordingly, while also considering other causes for the patient''s agitation.', 'Anaesthesia & Perioperative Care', '💉'),
(189, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is administering a sedative to a patient for a procedure. The nurse knows that the most common class of sedatives used for procedural sedation is:', '["Benzodiazepines", "Opioids", "Beta-blockers", "Antibiotics"]'::jsonb, 0, 'Benzodiazepines, such as Midazolam, are the most common class of sedatives used for procedural sedation. They provide anxiolysis (anxiety reduction) and amnesia, which helps to make the patient more comfortable during the procedure.', 'Anaesthesia & Perioperative Care', '💉'),
(190, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient who is post-anesthesia. The patient is experiencing nausea and vomiting. The nurse should:', '["Administer an antiemetic as ordered", "Place the patient in a prone position", "Encourage the patient to eat a large meal", "Tell the patient to wait for the nausea to pass"]'::jsonb, 0, 'Post-operative nausea and vomiting (PONV) is a common side effect of anesthesia. The nurse should administer an antiemetic as ordered to relieve the patient''s symptoms and prevent further complications like aspiration. The patient should not be encouraged to eat, and a prone position is not appropriate.', 'Anaesthesia & Perioperative Care', '💉'),
(191, 'CCU Self-Assessment Practice MCQs', 'CCU self-assessment practice session, council preparatory class (uploaded)', 'A nurse is caring for a patient who is on a continuous sedative infusion. The nurse knows that the sedative should be weaned slowly to prevent:', '["A sudden increase in blood pressure", "The patient from waking up too quickly", "Withdrawal symptoms and rebound anxiety", "The patient from feeling pain"]'::jsonb, 2, 'A patient on a continuous sedative infusion for a prolonged period can become dependent on the medication. If the sedative is discontinued abruptly, the patient may experience withdrawal symptoms and rebound anxiety. The infusion should be weaned slowly to prevent these complications.', 'Anaesthesia & Perioperative Care', '💉'),
(192, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A nurse is watching the cardiac monitor and notices that the rhythm suddenly changes. There are no P waves, the QRS complexes are wide, and the ventricular rate is regular but over 100. The nurse determines that the client is experiencing:', '["Ventricular tachycardia", "Premature ventricular contractions", "Ventricular fibrillation", "Sinus tachycardia"]'::jsonb, 0, 'Wide QRS at a regular rate over 100 with no P waves is ventricular tachycardia.', 'Cardiovascular', '🫀'),
(193, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Which electrolyte would the nurse identify as the major electrolyte responsible for determining the concentration of the extracellular fluid?', '["Sodium", "Chloride", "Phosphate", "Bicarbonate"]'::jsonb, 0, 'Sodium is the main extracellular cation and sets ECF osmolality and concentration.', 'ABG & Electrolytes', '🩸'),
(194, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Which clinical manifestation would lead the nurse to suspect that a client is experiencing hypermagnesemia?', '["Increased respiratory rate and depth", "Soft-tissue calcification and hyperreflexia", "Hot flushed skin and diaphoresis", "Muscle pain and acute rhabdomyolysis"]'::jsonb, 2, 'Raised magnesium causes vasodilation (hot, flushed skin, sweating), hypotension, depressed reflexes and respiratory depression.', 'ABG & Electrolytes', '🩸'),
(195, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A patient is diagnosed with metabolic acidosis, which would the nurse expect the health care provider to order?', '["Bronchodilator", "Potassium", "Sodium bicarbonate", "Serum sodium level"]'::jsonb, 2, 'Severe metabolic acidosis may be treated with sodium bicarbonate, along with treating the cause.', 'ABG & Electrolytes', '🩸'),
(196, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Patient X is diagnosed with constipation. As a knowledgeable nurse, which nursing intervention is appropriate for maintaining normal bowel function?', '["Assessing dietary intake", "Decreasing fluid intake", "Providing limited physical activity", "Turning, coughing, and deep breathing"]'::jsonb, 0, 'Constipation care starts with assessing diet (fibre, fluid); then increase fluids and activity.', 'GI, Endocrine & Metabolic', '🍽️'),
(197, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Shared governance is practised in some wards. Which describes this style of leadership?', '["Leaders rely heavily on visioning and inspire members to achieve results", "Leaders believe people are basically good and need not be closely controlled", "Leadership is shared at the point of care", "The leader makes all decisions alone"]'::jsonb, 2, 'Shared governance spreads decision-making to the nurses at the point of care.', 'Ethics, Law & Management', '⚖️'),
(198, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'According to situational leadership theory, which style best fits followers who are self-directed, expert and mature?', '["Authoritarian", "Laissez-faire", "Bureaucratic", "Master - Servant"]'::jsonb, 1, 'Situational leadership: with mature, expert, self-directed followers, a hands-off (laissez-faire/delegating) style works best.', 'Ethics, Law & Management', '⚖️'),
(199, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A Chief Nurse Executive has a charismatic leadership style. Which of the following behaviors best describes this style?', '["Possesses inspirational quality that makes followers get attracted to him and regard him with reverence.", "Uses visioning as the core of his leadership.", "Acts as he does because he expects that his harshness will yield positive results.", "Acts as he does because he expects that his behavior will yield positive results."]'::jsonb, 0, 'Charismatic leaders have an inspirational personal quality that attracts devoted followers.', 'Ethics, Law & Management', '⚖️'),
(200, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'The nurse uses a stethoscope to auscultate a male patient’s chest. Which statement about a stethoscope with a bell and diaphragm is true?', '["The diaphragm detects low-pitched sounds best.", "The bell detects thrills best.", "The diaphragm detects high-pitched sounds best.", "The bell detects high-pitched sounds best."]'::jsonb, 2, 'The diaphragm picks up high-pitched sounds (breath sounds, S1/S2). The bell picks up low-pitched sounds (S3, S4, murmurs).', 'Mixed Revision', '📚'),
(201, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'To evaluate a patient for hypoxia, the physician is most likely to order which laboratory test?', '["Red blood cell count", "Arterial blood gas (ABG) analysis", "Sputum culture", "Total hemoglobin"]'::jsonb, 1, 'An ABG measures PaO2, SaO2 and PaCO2 directly, so it is the test for hypoxia.', 'Respiratory', '🫁'),
(202, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'The nurse is assessing a postoperative adult patient. Which of the following should the nurse document as subjective data?', '["Electrocardiographic (ECG) waveforms", "Vital signs", "Patient’s description of pain", "Laboratory test result"]'::jsonb, 2, 'Subjective data are what the patient reports, such as pain. Vital signs, ECGs and lab results are objective.', 'Research & Nursing Process', '📊'),
(203, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Which pulse should the nurse palpate during rapid assessment of an unconscious male adult?', '["Radial", "Brachial", "Carotid", "Femoral"]'::jsonb, 2, 'In an unconscious adult, check the carotid pulse. It persists when peripheral pulses are lost.', 'Cardiovascular', '🫀'),
(204, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'To ensure homogenization when diluting powdered medication in a vial, the nurse should:', '["Do nothing after adding the solution to the vial.", "Invert the vial and let it stand for 1 minute.", "Shake the vial vigorously.", "Roll the vial gently between the palms."]'::jsonb, 3, 'Roll the vial gently to mix the powder. Shaking causes foaming and can damage some drugs.', 'ICU Pharmacology', '💊'),
(205, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'You have a patient that might have a urinary tract infection (UTI). Which statement by the patient suggests that a UTI is likely?', '["“I pee a lot.”", "“It burns when I pee.”", "“I go hours without the urge to pee.”", "“My pee smells sweet.”"]'::jsonb, 1, 'Dysuria (burning on urination) is a classic UTI symptom.', 'Renal & Fluid Balance', '💧'),
(206, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Which of the following symptoms do you expect to see in a patient diagnosed with acute pyelonephritis?', '["Costovertebral angle tenderness and chills", "Jaundice and flank pain", "Polyuria and nocturia", "Burning sensation on urination"]'::jsonb, 0, 'Acute pyelonephritis causes fever, chills and costovertebral angle (flank) tenderness.', 'Renal & Fluid Balance', '💧'),
(207, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'In emergency treatment of impending anaphylaxis from a drug, which action comes FIRST among these?', '["Obtaining a Full blood count (FBC).", "Administering oxygen.", "Inserting an I.V. catheter.", "Taking vital signs."]'::jsonb, 1, 'In anaphylaxis, secure the airway and oxygenation first, then give IM adrenaline and get IV access.', 'ICU Pharmacology', '💊'),
(208, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Emergency treatment of a client in status asthmaticus includes which of the following medications?', '["Inhaled beta-adrenergic agents", "Inhaled corticosteroids", "I.V. beta-adrenergic agents", "Oral corticosteroids"]'::jsonb, 0, 'Status asthmaticus is treated first with inhaled (nebulised) short-acting β2-agonists, plus systemic steroids and oxygen.', 'Respiratory', '🫁'),
(209, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Clients with chronic obstructive bronchitis are given diuretic therapy. Which of the following reasons best explains why?', '["Reducing fluid volume improves clients’ mobility.", "Reducing fluid volume reduces oxygen demand.", "Restricting fluid volume reduces sputum production.", "Reducing fluid volume improves respiratory function."]'::jsonb, 1, 'In chronic bronchitis with cor pulmonale, diuretics reduce fluid overload and so ease cardiac workload and oxygen demand.', 'Respiratory', '🫁'),
(210, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Exercise has which of the following effects on clients with asthma, chronic bronchitis, and emphysema?', '["It worsens respiratory function and is discouraged.", "It reduces the number of acute attacks.", "It enhances cardiovascular fitness.", "It improves respiratory muscle strength."]'::jsonb, 2, 'Regular exercise improves cardiovascular fitness and exercise tolerance in chronic lung disease, as in pulmonary rehabilitation.', 'Respiratory', '🫁'),
(211, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Which of these best describes the function of a ventilator?', '["A life-support device that moves air into and out of the lungs to maintain bodily function", "A machine that records the electrical activity of the heart", "A device that assesses cardiac function during maximal exercise", "A device that analyses heart rhythm and delivers a shock"]'::jsonb, 0, 'A ventilator is a life-support machine that moves gas in and out of the lungs to keep the body functioning.', 'Respiratory', '🫁'),
(212, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Which of the following phrases would be found in a report of a qualitative study?', '["\"The control group received no instruction?\"", "\"The hypothesis of this study is?\"", "\"Subjects were asked to relate their perceptions of pain?\"", "\"Perceived pain was measured using the nominal pain scale?\""]'::jsonb, 2, 'Qualitative studies explore participants'' own perceptions and experiences, e.g. asking them to describe their pain.', 'Research & Nursing Process', '📊'),
(213, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'For which of the following research questions would qualitative methods be most appropriate?', '["What is the meaning of health to farmer?", "Under what conditions does a decubitus ulcer heal most quickly?", "Which pain medications decrease the need for sleep medication in elderly patients?", "How does frequency of medication administration impact the degree of pain experienced following knee replacement surgery?"]'::jsonb, 0, '"What is the meaning of health to farmers?" explores meaning and experience, which suits qualitative methods.', 'Research & Nursing Process', '📊'),
(214, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'While caring for a client who has sustained an MI, the nurse notes eight PVCs in one minute on the cardiac monitor. The client is receiving an IV infusion of D5W and oxygen at 2 L/minute. The nurse’s first course of action should be to:', '["Increase the oxygen concentration.", "Increase the IV infusion rate", "Notify the physician promptly.", "Administer a prescribed analgesic."]'::jsonb, 2, 'Frequent PVCs (more than 6 per minute) after MI warn of ventricular irritability. Notify the physician promptly.', 'Cardiovascular', '🫀'),
(215, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'The adaptations of a client with complete heart block would most likely include:', '["Flushing and slurred speech", "Cephalalgia and blurred vision", "Syncope and slow ventricular rate", "Nausea and vertigo"]'::jsonb, 2, 'Complete heart block gives a slow ventricular escape rhythm, which can cause syncope (Stokes–Adams attacks).', 'Cardiovascular', '🫀'),
(216, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'When ventricular fibrillation occurs in a CCU, the first person reaching the client should:', '["Defibrillate the client.", "Administer oxygen.", "Administer sodium bicarbonate intravenously.", "Initiate CPR."]'::jsonb, 0, 'VF needs immediate defibrillation. When a defibrillator is at hand, it comes first.', 'Cardiovascular', '🫀'),
(217, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'When auscultating the apical pulse of a client who has atrial fibrillation, the nurse would expect to hear a rhythm that is characterized by:', '["A continuous and totally unpredictable irregularity.", "Long pauses in an otherwise regular rhythm.", "Slow but strong and regular beats.", "The presence of occasional coupled beats."]'::jsonb, 0, 'Atrial fibrillation is "irregularly irregular": completely unpredictable.', 'Cardiovascular', '🫀'),
(218, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Atherosclerosis impedes coronary blood flow by which of the following mechanisms?', '["Hardened vessels dilate to allow blood to flow through.", "Plaques obstruct the vein.", "Plaques obstruct the artery.", "Blood clots form outside the vessel wall."]'::jsonb, 2, 'Atherosclerotic plaques narrow and obstruct the coronary arteries.', 'Cardiovascular', '🫀'),
(219, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A paradoxical pulse occurs in a client who had a coronary artery bypass graft (CABG) surgery two (2) days ago. Which of the following surgical complications should the nurse suspect?', '["Left-sided heart failure", "Complete heart block", "Pericardial tamponade", "Aortic regurgitation"]'::jsonb, 2, 'Pulsus paradoxus (systolic fall over 10 mmHg on inspiration) after cardiac surgery suggests cardiac tamponade.', 'Cardiovascular', '🫀'),
(220, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A woman with severe mitral stenosis and mitral regurgitation has a pulmonary artery catheter inserted. The physician orders pulmonary artery pressure monitoring, including pulmonary capillary wedge pressures. The purpose of this is to help assess the:', '["Oxygen and carbon dioxide concentration is the blood.", "Pressure from fluid within the left ventricle.", "Peripheral arterial pressure.", "Degree of coronary artery stenosis."]'::jsonb, 1, 'PCWP estimates left atrial pressure and so left ventricular filling (end-diastolic) pressure.', 'Cardiovascular', '🫀'),
(221, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A nurse notices frequent artifacts on the ECG monitor for a client whose leads are connected by cable to a console at the bedside. The nurse examines the client to determine the cause. Which of the following items is unlikely to be responsible for the artifact?', '["Frequent movement of the client.", "Leads applied to the limbs.", "Tightly secured cable connections.", "Leads applied over hairy areas."]'::jsonb, 2, 'Movement, limb leads and hair cause artefact. Tight, secure cable connections reduce it.', 'Cardiovascular', '🫀'),
(222, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A nurse is assessing an electrocardiogram rhythm strip. The P waves and QRS complexes are regular. The PR interval is 0.16 second, and QRS complexes measure 0.06 second. The overall heart rate is 64 beats per minute. The nurse assesses the cardiac rhythm as:', '["Sick sinus syndrome", "Sinus bradycardia", "First-degree heart block", "Normal sinus rhythm"]'::jsonb, 3, 'Rate 64, regular, PR 0.16 s (normal 0.12–0.20) and QRS 0.06 s (under 0.12) is normal sinus rhythm.', 'Cardiovascular', '🫀'),
(223, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A 66-year-old client has marked dyspnea at rest, is thin, and uses accessory muscles to breathe. He’s tachypneic, with a prolonged expiratory phase. He has no cough. He leans forward with his arms braced on his knees to support his chest and shoulders for breathing. This client has symptoms of which of the following respiratory disorders?', '["Asthma", "Emphysema", "ARDS", "Chronic obstructive bronchitis"]'::jsonb, 1, 'A thin "pink puffer" with dyspnoea at rest, accessory muscle use, prolonged expiration, tripod posture and little cough is emphysema.', 'Respiratory', '🫁'),
(224, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A 58-year-old client with a 40-year history of smoking one to two packs of cigarettes a day has a chronic cough producing thick sputum, peripheral edema, and cyanotic nail beds. Based on this information, he most likely has which of the following conditions?', '["Emphysema", "Adult respiratory distress syndrome (ARDS)", "Asthma", "Chronic obstructive bronchitis"]'::jsonb, 3, 'A heavy smoker with chronic productive cough, oedema and cyanosis is a "blue bloater": chronic bronchitis.', 'Respiratory', '🫁'),
(225, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A 19-year-old comes into the emergency department with acute asthma. His respiratory rate is 44 breaths/minute, and he appears to be in acute respiratory distress. Which of the following actions should be taken FIRST?', '["Take a full medication history.", "Apply a cardiac monitor to the client.", "Provide emotional support to the client.", "Give a bronchodilator by nebulizer."]'::jsonb, 3, 'In acute severe asthma, give a nebulised bronchodilator first. History can wait.', 'Respiratory', '🫁'),
(226, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A client with acute asthma showing inspiratory and expiratory wheezes and a decreased expiratory volume should be treated with which of the following classes of medication right away?', '["Inhaled steroids", "Beta-adrenergic blockers", "Bronchodilators", "Oral steroids"]'::jsonb, 2, 'Acute bronchospasm is treated immediately with bronchodilators (inhaled β2-agonists).', 'Respiratory', '🫁'),
(227, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Which of the following types of asthma involves an acute asthma attack brought on by an upper respiratory infection?', '["Intrinsic", "Extrinsic", "Meditated", "Emotional"]'::jsonb, 0, 'Intrinsic (non-allergic) asthma is triggered by infection, exercise, cold and similar factors. Extrinsic asthma is allergic.', 'Respiratory', '🫁'),
(228, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Which of the following assessment findings would help confirm a diagnosis of asthma in a client suspected of having the disorder?', '["Normal breath sounds", "Circumoral cyanosis", "Increased forced expiratory volume", "Inspiratory and expiratory wheezing"]'::jsonb, 3, 'Wheeze on inspiration and expiration with reduced expiratory flow supports asthma.', 'Respiratory', '🫁'),
(229, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A 7-year-old client is brought to the E.R. He’s tachypneic and afebrile and has a respiratory rate of 36 breaths/minute and a nonproductive cough. He recently had a cold. From his history, the client may have which of the following?', '["Acute asthma", "Chronic obstructive pulmonary disease (COPD)", "Emphysema", "Bronchial pneumonia"]'::jsonb, 0, 'A tachypnoeic, afebrile child with a dry cough after a recent cold fits acute asthma.', 'Respiratory', '🫁'),
(230, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Which of the following pathophysiological mechanisms that occur in the lung parenchyma allows pneumonia to develop?', '["Inflammation", "Bronchiectasis", "Atelectasis", "Effusion"]'::jsonb, 0, 'Pneumonia is inflammation of the lung parenchyma, with alveoli filling with exudate.', 'Respiratory', '🫁'),
(231, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'An elderly client with pneumonia may appear with which of the following symptoms first?', '["Fever and chills", "Hemoptysis and dyspnea", "Altered mental status and dehydration", "Pleuritic chest pain and cough"]'::jsonb, 2, 'Older people with pneumonia often present first with confusion and dehydration rather than fever or cough.', 'Respiratory', '🫁'),
(232, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'The major effect of acidosis on the central nervous system is:', '["Depression (confusion, lethargy, coma)", "Overexcitement (tetany, seizures)", "No effect at all", "Improved alertness"]'::jsonb, 0, 'Acidosis mainly DEPRESSES the CNS (confusion, coma). Alkalosis causes excitability (tetany, seizures).', 'ABG & Electrolytes', '🩸'),
(233, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'What two organs in the body serve as a compensatory function to maintain acid-base balance?', '["Kidneys and Lungs", "Lungs and Spleen", "Heart and Liver", "Gallbladder and Appendix"]'::jsonb, 0, 'The lungs (CO2) and kidneys (HCO3⁻, H⁺) compensate to keep the pH in balance.', 'ABG & Electrolytes', '🩸'),
(234, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Which acid–base disorder is characterised primarily by a LOW plasma PaCO2?', '["Metabolic Acidosis", "Respiratory Alkalosis", "Metabolic Alkalosis", "Respiratory Acidosis"]'::jsonb, 1, 'A low PaCO2 from hyperventilation is the primary change in respiratory alkalosis.', 'ABG & Electrolytes', '🩸'),
(235, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'In a patient undergoing surgery, it was vital to aspirate the contents of the upper gastrointestinal tract. After the operation, the following values were acquired from an arterial blood sample: pH 7.55, PCO2 52 mm Hg and HCO3- 40 mmol/l. What is the underlying disorder?', '["Respiratory Acidosis", "Respiratory Alkalosis", "Metabolic Acidosis", "Metabolic Alkalosis"]'::jsonb, 3, 'pH 7.55 (alkalosis) with HCO3⁻ 40 (high) is metabolic alkalosis from loss of gastric acid. The raised PCO2 is respiratory compensation.', 'ABG & Electrolytes', '🩸'),
(236, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A young woman is found comatose, having taken an unknown number of sleeping pills an unknown time before. An arterial blood sample yields the following values: pH 6.90, HCO3- 13 meq/liter, and PaCO2 68 mmHg. This patient’s acid-base status is most accurately described as:', '["Simultaneous Respiratory and Metabolic Acidosis", "Respiratory Acidosis", "Metabolic Acidosis", "Respiratory Acidosis with Complete Renal Compensation"]'::jsonb, 0, 'pH 6.90 with high PaCO2 (68) AND low HCO3⁻ (13) is combined respiratory and metabolic acidosis.', 'ABG & Electrolytes', '🩸'),
(237, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'A mother is admitted to the emergency department following complaints of fever and chills. The nurse on duty took her vital signs and noted the following: Temp = 100 °F; apical pulse = 95; respiration = 20 and deep. Measurement of arterial blood gas shows pH 7.37, PaO2 90 mm Hg, PaCO2 40 mm Hg, and HCO3 24 mmol/L. What is your assessment?', '["Hypothermia", "Hypothermia and Respiratory Alkalosis", "Hyperthermia", "Hyperthermia and Respiratory Alkalosis"]'::jsonb, 2, 'The ABG is normal (pH 7.37, PaCO2 40, HCO3⁻ 24). The only abnormality is a raised temperature (100 °F): hyperthermia.', 'ABG & Electrolytes', '🩸'),
(238, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'An elementary student, was rushed to the hospital due to vomiting and a decreased level of consciousness. The patient displays slow and deep (Kussmaul breathing), and he is lethargic and irritable in response to stimulation. He appears to be dehydrated—his eyes are sunken and mucous membranes are dry—and he has a two-week history of polydipsia, polyuria, and weight loss. Measurement of arterial blood gas shows pH 7.0, PaO2 90 mm Hg, PaCO2 23 mm Hg, and HCO3 12 mmol/L; other results are Na+ 126 mmol/L, K+ 5 mmol/L, and Cl- 95 mmol/L. What is your assessment?', '["Metabolic Acidosis, Partially, Compensated", "Metabolic Alkalosis, Uncompensated", "Respiratory Acidosis, Partially Compensated", "Respiratory Acidosis, Uncompensated"]'::jsonb, 0, 'pH 7.0 with low HCO3⁻ (12) is metabolic acidosis (DKA). The low PaCO2 (23) is partial respiratory compensation.', 'ABG & Electrolytes', '🩸'),
(239, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'George Kent is a 54-year-old widower with a history of chronic obstructive pulmonary disease and was rushed to the emergency department with increasing shortness of breath, pyrexia, and a productive cough with yellow-green sputum. He has difficulty communicating because of his inability to complete a sentence. One of his sons, Jacob, says he has been unwell for three days. Upon examination, crackles and wheezes can be heard in the lower lobes; he has tachycardia and a bounding pulse. Measurement of arterial blood gas shows pH 7.3, PaCO2 68 mm Hg, HCO3 28 mmol/L, and PaO2 60 mm Hg. How would you interpret this?', '["Metabolic Alkalosis, Uncompensated", "Metabolic Acidosis, Partially Compensated", "Respiratory Acidosis, Uncompensated", "Respiratory Acidosis, Partially Compensated"]'::jsonb, 3, 'pH 7.30 with high PaCO2 (68) is respiratory acidosis. HCO3⁻ 28 (raised) means partial renal compensation.', 'ABG & Electrolytes', '🩸'),
(240, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'WHICH OF THESE BEST DESCRIBES A COMPUTER', '["A device used only for playing games", "The means of connection between a sender and a receiver", "A collection of data being transmitted", "An electronic device that accepts data, processes and stores it, and gives out information"]'::jsonb, 3, 'A computer is an electronic device that accepts, processes and stores data and outputs information.', 'Nursing Informatics & ICT', '💻'),
(241, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'What is a computer file?', '["A property or characteristic of an entity", "The meaningful output obtained after processing data", "A collection of related records stored electronically under a file name", "An object, idea or person about which data are collected"]'::jsonb, 2, 'A computer file is a collection of related records stored electronically under a file name.', 'Nursing Informatics & ICT', '💻'),
(242, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'ONE OF THESE IS NOT AN ADVANTAGE OF COMPUTER FILES', '["It is relatively easy to reproduce or duplicate", "it is hard to use", "it enhances security of data if proper precautions are taken", "it offers faster access and retrieval of data"]'::jsonb, 1, 'Computer files are easy to copy, secure when protected, and quick to retrieve. Being "hard to use" is not an advantage.', 'Nursing Informatics & ICT', '💻'),
(243, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'What does it mean to double click?', '["to press the right mouse button once", "to press the left mouse button once", "to press the left mouse button twice in quick succession.", "to press the right mouse button twice in quick succession."]'::jsonb, 2, 'Double-clicking means pressing the left mouse button twice in quick succession.', 'Nursing Informatics & ICT', '💻'),
(244, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'One of these is not a function of the Mouse', '["to open or execute a program", "to move the mouse cursor", "to display a menu", "to type text"]'::jsonb, 3, 'A mouse moves the cursor, opens programs and shows menus. Typing text is done with the keyboard.', 'Nursing Informatics & ICT', '💻'),
(245, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'The computer mouse is_________________', '["an output device", "an input device", "a storage device", "a processing device"]'::jsonb, 1, 'The mouse is an input device.', 'Nursing Informatics & ICT', '💻'),
(246, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'The word Nurse originated from _______________', '["from the latin word Nutrix", "from the spanish word Nature", "from the french word Nourriture", "from the german word Nahrung"]'::jsonb, 0, '"Nurse" comes from the Latin nutrix, "to nourish".', 'Mixed Revision', '📚'),
(247, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Concerning medications used in COPD, which is NOT a usual part of treatment?', '["Anticoagulant", "Relievers", "Flu vaccine", "Preventers"]'::jsonb, 0, 'COPD is treated with relievers, preventers and vaccines (influenza, pneumococcal). Anticoagulants are not routine COPD treatment.', 'Respiratory', '🫁'),
(248, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Which of the following is not an obstetric cause of disseminated intravascular coagulopathy;', '["Pre-eclampsia/eclampsia", "Uterine inversion", "Amniotic fluid embolism", "Abruptio placentae"]'::jsonb, 1, 'Obstetric causes of DIC include abruption, amniotic fluid embolism, pre-eclampsia/HELLP and sepsis. Uterine inversion causes haemorrhage and shock rather than DIC.', 'Obstetric & Neonatal', '🤱'),
(249, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'The aims of barrier nursing in CCU is', '["Protect medical staff against infection", "Aimed at controlling and preventing the spread of infection", "Protect patients with highly infectious disease from spreading pathogens to othernon infected patients", "All of the above"]'::jsonb, 3, 'Barrier nursing protects staff, prevents spread from infected patients and controls infection overall.', 'Infection Prevention', '🦠'),
(250, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'One of these is a method of isolation __________', '["Infectious disease unit", "Strick universal precaution", "Ultraclean wards", "Segregation into single rooms"]'::jsonb, 3, 'Isolating patients in single rooms (segregation) is a basic method of isolation.', 'Infection Prevention', '🦠'),
(251, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'In reseach, the statement that explains why the study is important is: ____________', '["Significance of the study", "Objectiveof the study", "Statementof the study", "Background of the study"]'::jsonb, 0, 'The significance of the study explains why it matters and who will benefit.', 'Research & Nursing Process', '📊'),
(252, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'In research study where the researcher present what he hopes to achieve at the end of study will be expressed under:', '["Aims/purpose of the study", "Background of the study", "Statement of the problem", "Objectives of the study"]'::jsonb, 0, 'The aims or purpose state what the researcher hopes to achieve by the end of the study.', 'Research & Nursing Process', '📊'),
(253, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Data collection techniques include the following EXCEPT', '["Descriptive survey method", "interview", "Review of records", "Observation"]'::jsonb, 0, 'Interviews, observation and record review are data-collection techniques. A descriptive survey is a research design.', 'Research & Nursing Process', '📊'),
(254, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'One of these is an indication for a permanent pacemaker', '["Tachyarrthymias", "Carotid sinus syndrome", "Complete heart block", "Myocardial infarction"]'::jsonb, 2, 'Complete (third-degree) heart block is a classic indication for a permanent pacemaker.', 'Cardiovascular', '🫀'),
(255, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'Elecrocardiography can be defined as: ___________', '["A process of recording and analysis of electrical activities of the heart", "The instrument used to measure electrical activity of the heart", "An electrodes/lead to measure electrical activity of the heart", "A graphic record of the electrical activity of the heart"]'::jsonb, 0, 'Electrocardiography is recording and analysing the heart''s electrical activity. The ECG is the graphic record it produces.', 'Cardiovascular', '🫀'),
(256, 'Mock Examination 3', 'Mock 3 examination (uploaded)', 'All are sites of ectopic pregnancy implantation EXCEPT', '["Ovary", "Uterus", "Fallopian tube", "Cervix"]'::jsonb, 1, 'Ectopic pregnancy implants outside the uterine cavity: tube (most common), ovary, cervix or abdomen.', 'Obstetric & Neonatal', '🤱'),
(257, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'An anaesthetic agent contraindicated in hypertensive patients is:', '["Propofol", "Ketamine", "Thiopentone sodium", "Diazepam"]'::jsonb, 1, 'Ketamine stimulates the sympathetic nervous system, raising BP and heart rate, so avoid it in uncontrolled hypertension.', 'Anaesthesia & Perioperative Care', '💉'),
(258, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Vasoconstrictors (e.g. adrenaline) added to local anaesthetics are contraindicated in:', '["Regional anaesthesia", "Spinal anaesthesia", "Epidural anaesthesia", "Digital nerve block"]'::jsonb, 3, 'Adrenaline-containing local anaesthetics are avoided in digital (finger/toe), penile and similar end-artery blocks because of the risk of ischaemia.', 'Anaesthesia & Perioperative Care', '💉'),
(259, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which is correct regarding colour coding of anaesthetic gas cylinders?', '["Oxygen – black with grey shoulders", "Nitrous oxide – blue", "Helium – orange", "Cyclopropane – red"]'::jsonb, 1, 'Cylinder colours (ISO): oxygen white (UK: black body with white shoulders), nitrous oxide blue, CO2 grey, cyclopropane orange, helium brown.', 'Anaesthesia & Perioperative Care', '💉'),
(260, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'The preferred muscle relaxant in a patient with liver or renal failure is:', '["Rocuronium", "Pancuronium", "Vecuronium", "Atracurium"]'::jsonb, 3, 'Atracurium (and cisatracurium) is broken down by Hofmann elimination and ester hydrolysis, without needing the liver or kidneys.', 'Anaesthesia & Perioperative Care', '💉'),
(261, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'All of these ventilation modes may be used for weaning EXCEPT:', '["Assist-control ventilation", "Pressure support ventilation (PSV)", "Synchronised intermittent mandatory ventilation (SIMV)", "Controlled mechanical ventilation (CMV)"]'::jsonb, 3, 'Weaning uses modes that let the patient breathe spontaneously (PSV, SIMV, assist modes). In CMV the patient makes no effort, so it is not a weaning mode.', 'Respiratory', '🫁'),
(262, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'A laryngeal mask airway may be used in all of the following EXCEPT:', '["During CPR", "In a difficult intubation", "In a patient with a large tumour in the oral cavity", "In a child having elective eye surgery"]'::jsonb, 2, 'An LMA sits in the hypopharynx, so a large tumour in the oral cavity or pharynx prevents correct placement.', 'Anaesthesia & Perioperative Care', '💉'),
(263, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'The following are used to prevent or treat postoperative nausea and vomiting after squint surgery in children EXCEPT:', '["Propofol", "Ketamine", "Dexamethasone", "Ondansetron"]'::jsonb, 1, 'Ondansetron and dexamethasone treat PONV and propofol is anti-emetic. Ketamine itself causes nausea and vomiting.', 'Anaesthesia & Perioperative Care', '💉'),
(264, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'All of the following are disadvantages of anaesthetic ether EXCEPT:', '["Induction is slow", "It lowers blood pressure and readily produces arrhythmias", "Cautery cannot be used", "It increases salivary and bronchial secretions"]'::jsonb, 1, 'Ether gives slow induction, is flammable (no cautery) and irritates the airway, but it keeps BP stable and rarely causes arrhythmias.', 'Anaesthesia & Perioperative Care', '💉'),
(265, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which anaesthetic agent can raise intracranial pressure?', '["Propofol", "Lignocaine", "Sevoflurane", "Thiopentone sodium"]'::jsonb, 2, 'Volatile agents such as sevoflurane are cerebral vasodilators and can raise intracranial pressure. Propofol, thiopentone and lignocaine lower it.', 'Anaesthesia & Perioperative Care', '💉'),
(266, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'One of the fastest-acting inhalational agents is:', '["Sevoflurane", "Ether", "Halothane", "Isoflurane"]'::jsonb, 0, 'Sevoflurane has low blood–gas solubility, so induction and recovery are fast; it is also pleasant to breathe, making it good for inhalational induction.', 'Anaesthesia & Perioperative Care', '💉'),
(267, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which agent is NOT used to produce induced (controlled) hypotension during surgery?', '["Esmolol", "Hydralazine", "Mephentermine", "Sodium nitroprusside"]'::jsonb, 2, 'Esmolol, hydralazine and sodium nitroprusside lower BP. Mephentermine is a sympathomimetic vasopressor that raises it.', 'Anaesthesia & Perioperative Care', '💉'),
(268, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which drug is used to treat postoperative shivering?', '["Suxamethonium", "Pethidine", "Atropine", "Thiopentone"]'::jsonb, 1, 'Pethidine (meperidine) is very effective against postoperative shivering. Tramadol and clonidine are alternatives.', 'Anaesthesia & Perioperative Care', '💉'),
(269, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which IV induction agent is most suitable for day-case surgery?', '["Diazepam", "Propofol", "Morphine", "Ketamine"]'::jsonb, 1, 'Propofol suits day-case surgery: rapid, clear-headed recovery with little hangover and anti-emetic properties.', 'Anaesthesia & Perioperative Care', '💉'),
(270, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which anaesthetic agent does NOT trigger malignant hyperthermia?', '["Thiopentone", "Suxamethonium", "Isoflurane", "Halothane"]'::jsonb, 0, 'Volatile agents (halothane, isoflurane) and suxamethonium trigger malignant hyperthermia. IV agents like thiopentone and propofol are safe.', 'Anaesthesia & Perioperative Care', '💉'),
(271, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which statement about etomidate is NOT true?', '["It is an intravenous anaesthetic", "It precipitates coronary insufficiency", "It inhibits cortisol synthesis", "It causes pain at the injection site"]'::jsonb, 1, 'Etomidate is cardiostable, which is why it is chosen in heart disease. It suppresses cortisol synthesis and causes injection pain and myoclonus.', 'Anaesthesia & Perioperative Care', '💉'),
(272, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which local anaesthetic belongs to the ester group?', '["Bupivacaine", "Procaine", "Lignocaine", "Mepivacaine"]'::jsonb, 1, 'Procaine is an ester. Amides have two "i"s in their name: lidocaine, bupivacaine, mepivacaine.', 'Anaesthesia & Perioperative Care', '💉'),
(273, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which antibacterial should be avoided with d-tubocurarine because it enhances neuromuscular blockade?', '["Cefotaxime", "Doxycycline", "Streptomycin", "Norfloxacin"]'::jsonb, 2, 'Aminoglycosides such as streptomycin reduce acetylcholine release and potentiate non-depolarising blockers, prolonging paralysis.', 'ICU Pharmacology', '💊'),
(274, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which muscle relaxant has the longest duration of action?', '["Atracurium", "Vecuronium", "Rocuronium", "Doxacurium"]'::jsonb, 3, 'Doxacurium is a long-acting non-depolarising relaxant (often over 100 minutes). Atracurium, vecuronium and rocuronium are intermediate-acting.', 'Anaesthesia & Perioperative Care', '💉'),
(275, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which is NOT an indication for endotracheal intubation?', '["Pneumothorax", "Maintenance of a patent airway", "To provide positive-pressure ventilation", "Pulmonary toilet (clearing secretions)"]'::jsonb, 0, 'Intubation is for airway protection and patency, positive-pressure ventilation and pulmonary toilet. A pneumothorax is treated with a chest drain.', 'Anaesthesia & Perioperative Care', '💉'),
(276, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'A recognised side effect of rapid high-dose fentanyl is:', '["Abdominal pain", "Hypertension", "Tachycardia", "Chest wall rigidity"]'::jsonb, 3, 'High-dose, rapid IV fentanyl can cause chest wall (truncal) rigidity that makes ventilation hard. It is reversed with naloxone or a muscle relaxant.', 'Anaesthesia & Perioperative Care', '💉'),
(277, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which statement about xenon anaesthesia is NOT true?', '["It is non-explosive", "It gives slow induction and slow recovery", "It has low blood–gas solubility", "It has minimal cardiovascular side effects"]'::jsonb, 1, 'Xenon is non-explosive, has very low blood–gas solubility (FAST induction and recovery) and minimal cardiovascular effects. It is limited by cost.', 'Anaesthesia & Perioperative Care', '💉'),
(278, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which of the following decreases EEG activity during anaesthesia?', '["Nitrous oxide", "Early hypoxia", "Ketamine", "Hypothermia"]'::jsonb, 3, 'Hypothermia slows cerebral metabolism and reduces EEG activity. Ketamine, N2O and early hypoxia tend to increase or activate it.', 'Anaesthesia & Perioperative Care', '💉'),
(279, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'The last eye muscle to be rendered akinetic by a retrobulbar block is the:', '["Superior rectus", "Superior oblique", "Inferior oblique", "Levator palpebrae superioris"]'::jsonb, 1, 'The superior oblique lies outside the muscle cone, so it is often the last muscle paralysed by a retrobulbar block.', 'Anaesthesia & Perioperative Care', '💉'),
(280, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which neuromuscular blocker has the fastest onset of action?', '["Vecuronium", "Mivacurium", "Succinylcholine", "Atracurium"]'::jsonb, 2, 'Succinylcholine (suxamethonium) acts in 30–60 seconds, the fastest onset, which is why it is used for rapid-sequence induction.', 'Anaesthesia & Perioperative Care', '💉'),
(281, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Which inhalational agent has the lowest blood–gas solubility coefficient?', '["Desflurane", "Sevoflurane", "Nitrous oxide", "Isoflurane"]'::jsonb, 0, 'Desflurane has the lowest blood–gas partition coefficient (about 0.42) of these agents, so its onset and offset are fastest.', 'Anaesthesia & Perioperative Care', '💉'),
(282, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Methaemoglobinaemia is classically caused by which local anaesthetic?', '["Procaine", "Bupivacaine", "Prilocaine", "Lignocaine"]'::jsonb, 2, 'Prilocaine''s metabolite (o-toluidine) oxidises haemoglobin to methaemoglobin, especially at high doses.', 'Anaesthesia & Perioperative Care', '💉'),
(283, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'An advantage of nasotracheal intubation is:', '["Easier oral hygiene", "Lower infection risk", "Less mucosal damage and bleeding", "Greater tube movement"]'::jsonb, 0, 'A nasal tube leaves the mouth free for oral hygiene and is better tolerated and more stable long term. It carries risks of epistaxis and sinusitis.', 'Anaesthesia & Perioperative Care', '💉'),
(284, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'The nerve most commonly stimulated to monitor neuromuscular blockade is the:', '["Ulnar", "Radial", "Facial", "Median"]'::jsonb, 0, 'Train-of-four monitoring usually stimulates the ulnar nerve and watches the adductor pollicis (thumb).', 'Anaesthesia & Perioperative Care', '💉'),
(285, 'Anaesthesia Questions & Answers', 'Anaesthesia Q&A set (uploaded)', 'Side effects of prolonged high-concentration oxygen therapy include all EXCEPT:', '["Absorption atelectasis", "Increased pulmonary compliance", "Endothelial damage", "Decreased vital capacity"]'::jsonb, 1, 'High FiO2 causes absorption atelectasis, endothelial (alveolar–capillary) damage and reduced vital capacity, which DEcrease compliance.', 'Respiratory', '🫁'),
(286, 'Ethical Principles MCQs', 'Ethical principles case MCQs (uploaded)', 'A nursing instructor tells students that the most important principle when caring for patients is to do no harm. This principle is:', '["Beneficence", "Justice", "Non-maleficence", "Veracity"]'::jsonb, 2, 'Non-maleficence means "first, do no harm". It runs from the Hippocratic Oath to the Nightingale Pledge.', 'Ethics, Law & Management', '⚖️'),
(287, 'Ethical Principles MCQs', 'Ethical principles case MCQs (uploaded)', 'A nurse notices a suspicious lesion on a neonate but, knowing it could worsen, does not report it, and the baby is sent home and deteriorates. This is:', '["Advertent negligence", "Assault", "Battery", "Inadvertent negligence"]'::jsonb, 0, 'Advertent negligence: the carer knows the likely harmful consequence of omitting a required action and omits it anyway, e.g. noticing a lesion and not acting.', 'Ethics, Law & Management', '⚖️'),
(288, 'Ethical Principles MCQs', 'Ethical principles case MCQs (uploaded)', 'A competent patient''s living will refuses aggressive cancer treatment, but the physician insists on chemotherapy for the patient''s benefit. The physician is exercising:', '["Paternalism", "Ideal beneficence", "Respect for autonomy", "Veracity"]'::jsonb, 0, 'Paternalism is overriding a competent patient''s known wishes (such as a living will refusing aggressive treatment) "for their own good".', 'Ethics, Law & Management', '⚖️'),
(289, 'Ethical Principles MCQs', 'Ethical principles case MCQs (uploaded)', 'A hospital has many unreported needle-stick injuries and incidents of workplace violence, with no reporting or compensation system for staff. The victims of maleficence here are the:', '["Communities", "Employees", "Families", "Patients"]'::jsonb, 1, 'Institutions owe their employees a safe workplace. Unreported needle-stick injuries and violence with no compensation harm the staff.', 'Ethics, Law & Management', '⚖️'),
(290, 'Ethical Principles MCQs', 'Ethical principles case MCQs (uploaded)', 'Increasing opioids to relieve a dying patient''s pain, even if it may hasten death, can be justified under the rule of double effect only if:', '["The act itself is good or neutral", "The intention is to relieve suffering, not to kill", "The good effect outweighs the bad effect, which is not the means to the good", "All of these conditions are met"]'::jsonb, 3, 'The doctrine of double effect allows an act with a foreseen bad effect, such as analgesia that may hasten death, only if the act itself is good, the intention is good, the bad effect is not the means, and the good outweighs the bad.', 'Ethics, Law & Management', '⚖️'),
(291, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Which of the following is a function of an ICU manager?', '["Bureaucracy", "Motivation", "Humility", "Oppression"]'::jsonb, 1, 'Motivating staff is a core managerial function. Bureaucracy and oppression are not functions.', 'Ethics, Law & Management', '⚖️'),
(292, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The first and most important function of a manager is:', '["Delegation", "Funding", "Planning", "Supervision"]'::jsonb, 2, 'Planning is the first and most important management function; all others depend on it.', 'Ethics, Law & Management', '⚖️'),
(293, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'A leadership style that does not take input from group members is:', '["Democratic", "Autocratic", "Participative", "Laissez-faire"]'::jsonb, 1, 'An autocratic leader makes decisions alone without input from the group.', 'Ethics, Law & Management', '⚖️'),
(294, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Which scholars contributed to the classical theory of organisation?', '["Frederick Taylor", "Henri Fayol", "Max Weber", "All of the above"]'::jsonb, 3, 'Classical organisation theory came from Taylor (scientific management), Fayol (administrative) and Weber (bureaucracy).', 'Ethics, Law & Management', '⚖️'),
(295, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The process of looking into the future towards attaining group goals is:', '["Planning", "Leadership", "Delegation", "Supervision"]'::jsonb, 0, 'Planning looks ahead and decides how the group''s goals will be achieved.', 'Ethics, Law & Management', '⚖️'),
(296, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The optimal approach to leadership (Managerial Grid) shows:', '["High concern for production only", "Low concern for production", "High concern for employees only", "High concern for both production and employees"]'::jsonb, 3, 'Blake and Mouton''s "team management" (9,9) style shows high concern for both production and people.', 'Ethics, Law & Management', '⚖️'),
(297, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The following are good qualities of a leader EXCEPT:', '["Visionary", "Knowledgeable", "Rich", "Integrity"]'::jsonb, 2, 'Good leaders have vision, knowledge and integrity. Wealth is not a leadership quality.', 'Ethics, Law & Management', '⚖️'),
(298, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Henri Fayol''s 14 principles include the following EXCEPT:', '["Division of labour", "Discipline", "Unity of command", "Strategic management"]'::jsonb, 3, 'Fayol''s principles include division of work, discipline and unity of command. Strategic management is not one.', 'Ethics, Law & Management', '⚖️'),
(299, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Maslow''s hierarchy of needs includes the following EXCEPT:', '["Safety and security needs", "Psychological needs", "Love and belonging", "Physiological needs"]'::jsonb, 1, 'Maslow''s needs are physiological, safety, love/belonging, esteem and self-actualisation. "Psychological need" is not one of the levels.', 'Ethics, Law & Management', '⚖️'),
(300, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The two major classical leadership theories are trait theory and:', '["Maslow theory", "Behavioural theory", "Expectancy theory", "Equity theory"]'::jsonb, 1, 'The two major groups of leadership theory are trait theories and behavioural theories.', 'Ethics, Law & Management', '⚖️'),
(301, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'A leadership style that is careless about both production and employees is:', '["Scientific", "Autocratic", "Laissez-faire", "Democratic"]'::jsonb, 2, 'A laissez-faire leader is hands-off and shows little concern for either production or people.', 'Ethics, Law & Management', '⚖️'),
(302, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The human relations approach implies that the organisation is:', '["The property of the manager", "A group of people whose efforts are closely related and contribute to organisational objectives", "A group working only for individual success", "A machine that replaces people"]'::jsonb, 1, 'The human relations approach sees the organisation as people whose interrelated efforts contribute to shared objectives.', 'Ethics, Law & Management', '⚖️'),
(303, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'In Herzberg''s theory, the following are motivators EXCEPT:', '["Recognition", "Achievement", "Money (salary)", "Challenging work"]'::jsonb, 2, 'In Herzberg''s theory, recognition, achievement, responsibility and challenging work are motivators. Money (salary) is a hygiene factor.', 'Ethics, Law & Management', '⚖️'),
(304, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The following are functions of a manager EXCEPT:', '["Division", "Planning", "Organising", "Controlling"]'::jsonb, 0, 'The core functions of management are planning, organising, staffing, directing and controlling. "Division" is not a function.', 'Ethics, Law & Management', '⚖️'),
(305, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Which best captures the organising function of a manager?', '["Putting work together", "Delegating duties", "Breaking down work into operating duties and positions", "All of the above"]'::jsonb, 3, 'Organising means breaking work down into duties and positions, grouping them and delegating authority.', 'Ethics, Law & Management', '⚖️'),
(306, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The major concern of an effective leader is:', '["Concern for production only", "Concern for self", "Concern for both production and employees", "Concern for employees only"]'::jsonb, 2, 'Leaders combine concern for production (tasks) with concern for people.', 'Ethics, Law & Management', '⚖️'),
(307, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The process of using resources to attain organisational goals is:', '["Management", "Leadership", "Delegation", "Supervision"]'::jsonb, 0, 'Management is using resources to attain organisational goals.', 'Ethics, Law & Management', '⚖️'),
(308, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Which is NOT a function of a ward manager?', '["Malingering", "Planning", "Motivation", "Mentoring"]'::jsonb, 0, 'Malingering (faking illness to avoid work) is not a management function. Planning, motivation and mentoring are.', 'Ethics, Law & Management', '⚖️'),
(309, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Which is a quality of a good plan?', '["Specific", "Vague", "Unlimited in time", "Unrealistic"]'::jsonb, 0, 'A good plan is specific, measurable, achievable, realistic and time-bound (SMART).', 'Ethics, Law & Management', '⚖️'),
(310, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The following are qualities of a good leader EXCEPT:', '["Pride", "Integrity", "Vision", "Knowledge"]'::jsonb, 0, 'Integrity, vision and knowledge are leadership qualities. Pride is not.', 'Ethics, Law & Management', '⚖️'),
(311, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'An organisation''s resources cannot translate into goods and services without sound:', '["Control", "Management", "Mentoring", "Coordination"]'::jsonb, 1, 'Sound management turns an organisation''s resources into goods and services.', 'Ethics, Law & Management', '⚖️'),
(312, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Looking inward to overcome negativity and stay productive at work is called:', '["Self-control", "Self-awareness", "Self-management", "Self-esteem"]'::jsonb, 2, 'Self-management means regulating one''s own emotions and behaviour to stay productive despite negativity.', 'Ethics, Law & Management', '⚖️'),
(313, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The proponent of scientific management theory is:', '["Henri Fayol", "Frederick W. Taylor", "Adam Smith", "Max Weber"]'::jsonb, 1, 'Frederick W. Taylor proposed scientific management theory.', 'Ethics, Law & Management', '⚖️'),
(314, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The basis on which plans are made in an organisation is:', '["Strategic thinking", "Decision making", "Critical thinking", "Management meetings"]'::jsonb, 1, 'Planning rests on decision-making: choosing among alternatives.', 'Ethics, Law & Management', '⚖️'),
(315, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The following are part of Fayol''s 14 principles EXCEPT:', '["Division of labour", "Scalar chain", "Order", "Planning"]'::jsonb, 3, 'Fayol''s 14 principles include division of labour, scalar chain and order. Planning is a FUNCTION of management, not one of the principles.', 'Ethics, Law & Management', '⚖️'),
(316, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', '"The organisation is a complex whole with parts working together like the human body." Which theory fits this statement?', '["Humanist theory", "Classical theory", "Systems theory", "Human relations theory"]'::jsonb, 2, 'Systems theory sees the organisation as a complex whole of interdependent parts, like the human body.', 'Ethics, Law & Management', '⚖️'),
(317, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'A proponent of the human relations approach in management is:', '["Abraham Lincoln", "Max Weber", "John Maxwell", "Elton Mayo"]'::jsonb, 3, 'Elton Mayo (Hawthorne studies) founded the human relations approach.', 'Ethics, Law & Management', '⚖️'),
(318, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'What gives an employee''s work behaviour direction in response to intrinsic and extrinsic stimuli?', '["Compensation", "Motivation", "Reward", "Punishment"]'::jsonb, 1, 'Motivation is the internal or external drive that gives behaviour direction and intensity.', 'Ethics, Law & Management', '⚖️'),
(319, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Employees work harder in anticipation of reward for work done. Which theory best fits this?', '["Equity theory", "Maslow''s hierarchy", "Carrot-and-stick approach", "Expectancy theory"]'::jsonb, 3, 'Vroom''s expectancy theory: people work harder when they expect effort to bring a valued reward.', 'Ethics, Law & Management', '⚖️'),
(320, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The need for food, air, shelter and normal body functioning is called:', '["Physiological need", "Economic need", "Social need", "Esteem need"]'::jsonb, 0, 'Food, air, shelter and normal body function are physiological needs, the base of Maslow''s hierarchy.', 'Ethics, Law & Management', '⚖️'),
(321, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'In Herzberg''s theory, hygiene (maintenance) factors and motivators:', '["Hygiene factors are more important than motivators", "Motivators alone create motivation without hygiene factors", "The two operate entirely independently", "Work interdependently and complement each other"]'::jsonb, 3, 'In Herzberg''s theory, hygiene and motivator factors work together: removing dissatisfiers plus providing motivators gives effective motivation.', 'Ethics, Law & Management', '⚖️'),
(322, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The theory that individuals compare their job inputs and outcomes with others'' to remove inequities is:', '["Reinforcement theory", "Efficacy theory", "Equity theory", "Maslow''s hierarchy"]'::jsonb, 2, 'Equity theory (Adams): people compare their inputs and outcomes with others'' and act to remove perceived inequity.', 'Ethics, Law & Management', '⚖️'),
(323, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The process of interaction between two or more people in an organisation is:', '["Adaptation", "Interaction", "Induction", "Communication"]'::jsonb, 3, 'Communication is the interaction and exchange of information between two or more people.', 'Ethics, Law & Management', '⚖️'),
(324, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Planning that spans more than 5 years is:', '["Tactical planning", "Medium-term planning", "Operational planning", "Long-term planning"]'::jsonb, 3, 'Long-term (strategic) planning covers about 5 years or more.', 'Ethics, Law & Management', '⚖️'),
(325, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'In the communication cycle, the barrier present throughout is:', '["Distance", "Noise", "Interest", "Feedback"]'::jsonb, 1, 'Noise (any interference) can disrupt communication at every stage of the cycle.', 'Ethics, Law & Management', '⚖️'),
(326, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'In two-way communication, the response returned to the sender is:', '["Decoding", "Feedback", "Sending", "Encoding"]'::jsonb, 1, 'Feedback is the receiver''s response back to the sender, which makes communication two-way.', 'Ethics, Law & Management', '⚖️'),
(327, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Transmitting ideas through spoken or written words is called:', '["Effective communication", "Diagonal communication", "Verbal communication", "Non-verbal communication"]'::jsonb, 2, 'Verbal communication uses spoken or written words.', 'Ethics, Law & Management', '⚖️'),
(328, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Which is NOT a barrier to communication in health care?', '["Poor listening", "Semantic distortion", "Lack of trust", "Teamwork"]'::jsonb, 3, 'Poor listening, semantic distortion and lack of trust are barriers to communication. Teamwork helps it.', 'Ethics, Law & Management', '⚖️'),
(329, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Measuring the gap between actual and expected performance is:', '["Evaluation", "Training need analysis", "Control", "Planning"]'::jsonb, 0, 'Evaluation compares actual with expected performance to find the gap.', 'Ethics, Law & Management', '⚖️'),
(330, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The stages of team development include the following EXCEPT:', '["Forming", "Planning", "Norming", "Performing"]'::jsonb, 1, 'Tuckman''s team stages are forming, storming, norming, performing (and adjourning).', 'Ethics, Law & Management', '⚖️'),
(331, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The stage of team development usually characterised by conflict is:', '["Forming", "Storming", "Norming", "Performing"]'::jsonb, 1, 'Storming is the conflict stage, when members challenge roles and ideas.', 'Ethics, Law & Management', '⚖️'),
(332, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Conflict is dysfunctional when it causes ______ to the organisation.', '["Peace", "A positive effect", "A negative effect", "A neutral effect"]'::jsonb, 2, 'Conflict is dysfunctional when it harms the organisation''s performance.', 'Ethics, Law & Management', '⚖️'),
(333, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The following are benefits of teamwork EXCEPT:', '["Reduced medical errors", "Increased patient safety", "Improved productivity", "Creating ego"]'::jsonb, 3, 'Teamwork reduces errors, improves safety and raises productivity. It should not feed ego.', 'Ethics, Law & Management', '⚖️'),
(334, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The time-management matrix has how many quadrants?', '["2", "3", "5", "4"]'::jsonb, 3, 'Covey''s time-management matrix has 4 quadrants (urgent/important combinations).', 'Ethics, Law & Management', '⚖️'),
(335, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Which quadrant of the time-management matrix is most important for an effective manager?', '["Quadrant 1 (urgent and important)", "Quadrant 2 (important, not urgent)", "Quadrant 3 (urgent, not important)", "Quadrant 4 (neither)"]'::jsonb, 1, 'Quadrant 2 (important but not urgent: planning, prevention, development) is where effective managers should spend most time.', 'Ethics, Law & Management', '⚖️'),
(336, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'A leadership style that allows the opinion of the majority of group members is:', '["Democratic", "Autocratic", "Bureaucratic", "Laissez-faire"]'::jsonb, 0, 'Democratic leaders involve the group and go with majority opinion.', 'Ethics, Law & Management', '⚖️'),
(337, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Influencing and inspiring subordinates to achieve results is:', '["Management", "Control", "Leadership", "Administration"]'::jsonb, 2, 'Leadership is influencing and inspiring others to achieve results.', 'Ethics, Law & Management', '⚖️'),
(338, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'Must every leader be a manager and every manager be a leader?', '["Yes, always", "No", "Only in hospitals", "Only in the public sector"]'::jsonb, 1, 'Leadership and management overlap but are not the same: not every leader is a manager, and not every manager leads.', 'Ethics, Law & Management', '⚖️'),
(339, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The major obstacle to effective leadership in health is:', '["Lack of money", "Diversity", "Professionalism", "Lack of trust"]'::jsonb, 3, 'Trust is the basis of leadership. A lack of trust is a major obstacle to leading health teams.', 'Ethics, Law & Management', '⚖️'),
(340, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'The unwritten personal expectations an employee brings to an organisation are called the:', '["Official contract", "Personal ambition", "Psychological contract", "Job description"]'::jsonb, 2, 'The psychological contract is the unwritten set of personal expectations an employee brings to the organisation.', 'Ethics, Law & Management', '⚖️'),
(341, 'Management & Leadership MCQs', 'Management and Leadership MCQs (uploaded)', 'According to trait theory, leaders are:', '["Born with inherent leadership traits", "Made only through training", "Chosen by election", "Determined only by the situation"]'::jsonb, 0, 'Trait theory holds that leaders are born with certain inherent qualities.', 'Ethics, Law & Management', '⚖️'),
(342, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'What is the primary indication for chest tube insertion?', '["Pneumonia", "Pneumothorax", "Bronchitis", "Asthma"]'::jsonb, 1, 'The main indication for a chest drain is pneumothorax. It is also used for haemothorax, empyema and large effusions.', 'Respiratory', '🫁'),
(343, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'Which site is commonly used for chest tube insertion?', '["Midline of the abdomen", "5th intercostal space, mid-axillary line", "Clavicular notch", "4th intercostal space, midclavicular line"]'::jsonb, 1, 'Chest drains usually go in the "safe triangle": 4th–5th intercostal space, mid-axillary line.', 'Respiratory', '🫁'),
(344, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'What is the purpose of a chest tube?', '["To administer medications", "To remove air, fluid or pus from the pleural space", "To measure blood pressure", "To provide oxygen therapy"]'::jsonb, 1, 'A chest tube removes air, fluid, blood or pus from the pleural space so the lung can re-expand.', 'Respiratory', '🫁'),
(345, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'Which is NOT a contraindication to chest tube insertion?', '["Uncontrolled bleeding disorder", "Skin infection at the insertion site", "Suspected tension pneumothorax", "Refusal by a competent patient"]'::jsonb, 2, 'Tension pneumothorax is an INDICATION (after needle decompression) for a chest drain. Coagulopathy and skin infection at the site are relative contraindications.', 'Respiratory', '🫁'),
(346, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'What type of anaesthesia is usually used for chest tube insertion?', '["General anaesthesia", "Local anaesthesia", "Spinal anaesthesia", "No anaesthesia"]'::jsonb, 1, 'Chest drains are usually inserted under local anaesthetic infiltration, with analgesia or sedation as needed.', 'Respiratory', '🫁'),
(347, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'The purpose of the underwater seal in chest drainage is to:', '["Filter air entering the chest", "Prevent air from re-entering the pleural space during inspiration", "Humidify the air", "Increase airflow into the pleural space"]'::jsonb, 1, 'The water seal is a one-way valve: air and fluid leave the chest but cannot be drawn back in on inspiration.', 'Respiratory', '🫁'),
(348, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'A properly functioning underwater-seal drain typically shows:', '["Continuous bubbling in the water-seal chamber", "No movement at all in the water-seal chamber", "Fluctuation (tidaling) and intermittent bubbling with respiration", "A water level that never moves"]'::jsonb, 2, 'A working drain shows "tidaling" (the fluid swinging with breathing) and sometimes intermittent bubbling when air is draining.', 'Respiratory', '🫁'),
(349, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'Continuous bubbling in the water-seal chamber may indicate:', '["Normal operation", "An air leak", "A blocked tube", "Full lung re-expansion"]'::jsonb, 1, 'Continuous bubbling in the water-seal chamber means an air leak, from the patient or the system.', 'Respiratory', '🫁'),
(350, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'The recommended position for a patient with a chest tube is:', '["Supine", "Prone", "Upright or semi-Fowler''s", "Trendelenburg"]'::jsonb, 2, 'Semi-Fowler''s or upright positioning helps lung expansion and drainage.', 'Respiratory', '🫁'),
(351, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'What is hypothermia?', '["Body temperature rising above normal", "Body temperature falling below normal (core <35 °C)", "Body temperature remaining constant", "A condition of high blood pressure"]'::jsonb, 1, 'Hypothermia is a fall in core body temperature below normal, under 35 °C.', 'Mixed Revision', '📚'),
(352, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'Which is NOT a common sign of established hypothermia?', '["Shivering", "Slurred speech", "Fast heartbeat", "Loss of coordination"]'::jsonb, 2, 'Shivering, slurred speech and incoordination are typical. Heart rate SLOWS as hypothermia deepens.', 'Mixed Revision', '📚'),
(353, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'Which groups are at higher risk of hypothermia?', '["Young adults", "Infants and the elderly", "Professional athletes", "People in tropical climates"]'::jsonb, 1, 'Infants (large surface area, poor thermoregulation) and the elderly are at highest risk.', 'Mixed Revision', '📚'),
(354, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'The best initial treatment for mild hypothermia is:', '["IV fluids", "Immersing the person in hot water", "Moving to a warm environment and providing dry clothing", "Giving caffeine"]'::jsonb, 2, 'For mild hypothermia: move to a warm place, remove wet clothes, give dry insulation and warm sweet drinks if alert.', 'Mixed Revision', '📚'),
(355, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'A common complication of severe hypothermia is:', '["Hyperactivity", "Increased body temperature", "Cardiac arrest (arrhythmias)", "Rapid breathing"]'::jsonb, 2, 'Severe hypothermia (below about 28–30 °C) causes bradycardia, VF and cardiac arrest.', 'Mixed Revision', '📚'),
(356, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'Which activity can increase the risk of hypothermia?', '["Swimming in cold water", "Running in hot weather", "Drinking hot beverages", "Wearing insulated clothing"]'::jsonb, 0, 'Cold-water immersion causes rapid heat loss: water conducts heat about 25 times faster than air.', 'Mixed Revision', '📚'),
(357, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'In severe hypothermia, what should be avoided during rewarming?', '["Rough handling or rubbing the extremities", "Removing wet clothing", "Insulating the body", "Moving the person to a warm environment"]'::jsonb, 0, 'In severe hypothermia handle gently and do not rub or massage the limbs; it can trigger arrhythmias and "afterdrop".', 'Mixed Revision', '📚'),
(358, 'Chest Tube & Hypothermia MCQs', 'Chest tube insertion and hypothermia questions (uploaded)', 'Which is NOT a method of preventing hypothermia?', '["Wearing layered clothing", "Staying dry", "Drinking alcohol to keep warm", "Avoiding prolonged cold exposure"]'::jsonb, 2, 'Alcohol causes vasodilation and heat loss. It does not keep you warm.', 'Mixed Revision', '📚'),
(359, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'Research usually starts with a problem and ends with:', '["A hypothesis", "Conclusions and recommendations (dissemination of findings)", "Data collection", "A literature review"]'::jsonb, 1, 'Research starts with a problem and ends with conclusions, recommendations and dissemination of findings.', 'Research & Nursing Process', '📊'),
(360, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'In research, the term "universe" refers to the:', '["Sample", "Entire population", "Research instrument", "Study setting"]'::jsonb, 1, 'The "universe" is the whole population: all the units of interest.', 'Research & Nursing Process', '📊'),
(361, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'All of the following are methods (sources) of problem-solving knowledge EXCEPT:', '["Tradition", "Assessment", "Voices of authority", "Logical reasoning"]'::jsonb, 1, 'Tradition, authority and logical reasoning are sources of knowledge or problem-solving. "Assessment" is not one of them.', 'Research & Nursing Process', '📊'),
(362, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'For children and incompetent persons, consent for research participation is obtained as:', '["Implied consent", "Proxy (surrogate) consent from parent/guardian, with the child''s assent", "Verbal consent only", "No consent needed"]'::jsonb, 1, 'Children and incompetent persons give assent; legal consent comes from a parent or guardian (proxy consent).', 'Research & Nursing Process', '📊'),
(363, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'The ethical principle of beneficence in research means:', '["Maintain confidentiality", "Keep anonymity and privacy", "Above all, do no harm", "Avoid plagiarism"]'::jsonb, 2, 'Beneficence in research means maximise benefit and, above all, do no harm. Confidentiality and anonymity belong to respect and privacy.', 'Research & Nursing Process', '📊'),
(364, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'Which step of the research process cuts across all the other steps?', '["Problem identification", "Literature review", "Research variables", "Hypothesis"]'::jsonb, 1, 'The literature review runs through the whole research process, from framing the problem to discussing findings.', 'Research & Nursing Process', '📊'),
(365, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'All the following are probability sampling methods EXCEPT:', '["Quota sampling", "Stratified sampling", "Cluster sampling", "Simple random sampling"]'::jsonb, 0, 'Quota sampling is non-probability. Stratified, cluster and simple random sampling are probability methods.', 'Research & Nursing Process', '📊'),
(366, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'A pilot study provides the opportunity to:', '["Publish the results early", "Test the research subjects", "Understand the research problem", "Test the research instrument"]'::jsonb, 3, 'A pilot study pre-tests the research instrument and procedures on a small group before the main study.', 'Research & Nursing Process', '📊'),
(367, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'Observation in research involves:', '["Watching behaviour in its natural setting", "Interviewing participants", "Recording everything that happens", "Reviewing records only"]'::jsonb, 0, 'Research observation means systematically watching behaviour in its natural setting.', 'Research & Nursing Process', '📊'),
(368, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'Probability sampling gives every member of the population:', '["Equal representation", "Guaranteed selection", "An equal chance of being selected", "No chance of selection"]'::jsonb, 2, 'Probability sampling gives every member of the population an equal (known, non-zero) chance of selection.', 'Research & Nursing Process', '📊'),
(369, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'The measure of location that divides a data set into two equal parts is the:', '["Median", "Mean", "Mode", "Range"]'::jsonb, 0, 'The median divides an ordered data set into two equal halves.', 'Research & Nursing Process', '📊'),
(370, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'Plagiarism means:', '["Literary theft", "Literary competence", "Literary appreciation", "Literary reference"]'::jsonb, 0, 'Plagiarism is literary theft: presenting others'' work as your own.', 'Research & Nursing Process', '📊'),
(371, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'Before conducting a research study it is essential to prepare the:', '["Research problem", "Research proposal", "Research report", "Research subjects"]'::jsonb, 1, 'A research proposal must be prepared, and usually approved, before the study begins.', 'Research & Nursing Process', '📊'),
(372, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'Evidence-based practice is formed from the following EXCEPT:', '["Clinical experience/expertise", "Hospital policy", "Research evidence", "Client values"]'::jsonb, 1, 'Evidence-based practice combines research evidence, clinical expertise and patient values. Hospital policy is not one of its three pillars.', 'Research & Nursing Process', '📊'),
(373, 'Research Methods MCQs', 'Research methods MCQ sheet (uploaded)', 'An acceptable reliability coefficient is:', '["Greater than 0.6–0.7", "1.01 to 1.05", "1.05 to 1.09", "Greater than 2.0"]'::jsonb, 0, 'Cronbach''s alpha (reliability) ranges from 0 to 1. Values of about 0.6–0.7 or more are usually accepted.', 'Research & Nursing Process', '📊'),
(374, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Exudative pleural fluid characteristically:', '["Is clear", "Does not clot", "Is usually bilateral", "Contains more than 3 g/dL of protein"]'::jsonb, 3, 'Exudates (Light''s criteria) have high protein (>3 g/dL), are often cloudy, may clot and are usually unilateral.', 'Respiratory', '🫁'),
(375, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which of the following causes an EXUDATIVE pleural effusion?', '["Pulmonary tuberculosis", "Constrictive pericarditis", "Nephrotic syndrome", "Meigs'' syndrome"]'::jsonb, 0, 'TB, pneumonia, malignancy and PE cause exudates. Nephrotic syndrome, constrictive pericarditis and Meigs'' syndrome classically cause transudates.', 'Respiratory', '🫁'),
(376, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Loculated pleural fluid on imaging:', '["Shifts the mediastinum towards the lesion", "Shifts the mediastinum to the opposite side", "Has a concave lateral meniscus", "Has a broad base with a well-defined convex medial margin"]'::jsonb, 3, 'Loculated fluid is trapped by adhesions. It forms a broad-based opacity with a well-defined convex medial margin and does not shift the mediastinum.', 'Radiology & Imaging', '🩻'),
(377, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'A transudate (clear fluid) on CT chest appears as:', '["Hypodense with strands", "Homogeneously hypodense with no strands", "Hyperdense with strands", "Hyperdense with air densities"]'::jsonb, 1, 'Simple transudate appears on CT as homogeneous low-density (water-density) fluid without septations or strands.', 'Radiology & Imaging', '🩻'),
(378, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which is NOT a sign of potential sepsis?', '["Tachycardia", "Tachypnoea", "Hypertension", "Raised white cell count"]'::jsonb, 2, 'Sepsis signs include tachycardia, tachypnoea, fever or hypothermia and abnormal WBC. HYPOtension, not hypertension, signals septic shock.', 'Shock & Haemorrhage', '⚡'),
(379, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which is NOT a marker of acute organ dysfunction?', '["Jaundice", "Thrombocytopenia", "Hypotension", "Decreased creatinine level"]'::jsonb, 3, 'Organ dysfunction markers include jaundice (liver), thrombocytopenia (coagulation) and hypotension. Creatinine RISES in kidney injury.', 'Shock & Haemorrhage', '⚡'),
(380, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which condition is LEAST likely to cause multiple organ dysfunction syndrome (MODS)?', '["Major burns", "Uncomplicated diabetes", "Acute pancreatitis", "Poisoning"]'::jsonb, 1, 'MODS follows severe insults: sepsis, burns, pancreatitis, trauma, poisoning. Uncomplicated diabetes is the least likely of these to cause it directly.', 'Shock & Haemorrhage', '⚡'),
(381, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which blood cells are commonly increased in MODS?', '["White blood cells", "Red blood cells", "Plasma cells", "Platelets"]'::jsonb, 0, 'MODS is driven by systemic inflammation, often with leucocytosis (raised white cells).', 'Shock & Haemorrhage', '⚡'),
(382, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which nutritional measure helps manage MODS?', '["Limiting all fluids", "A very high carbohydrate diet", "Providing early enteral feeds", "High-dose vitamin C alone"]'::jsonb, 2, 'Early enteral feeding supports gut integrity, reduces bacterial translocation and meets high metabolic demands in MODS.', 'Shock & Haemorrhage', '⚡'),
(383, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Risk factors for MODS include all EXCEPT:', '["Impaired immune response", "Older age", "Chronic illness", "Low socio-economic status"]'::jsonb, 3, 'MODS risk rises with older age, chronic illness and impaired immunity. Socio-economic status is not a direct physiological risk factor.', 'Shock & Haemorrhage', '⚡'),
(384, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'In a ventilated patient, which finding suggests MODS?', '["Increased serum albumin", "Decreased respiratory compliance", "Increased GI motility", "Decreased BUN/creatinine ratio"]'::jsonb, 1, 'Lung involvement in MODS (ARDS) shows as decreased respiratory compliance in ventilated patients.', 'Shock & Haemorrhage', '⚡'),
(385, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which test indicates chronic hyperglycaemia?', '["HbA1c", "Fasting blood sugar", "Oral glucose tolerance test", "Fasting lipid profile"]'::jsonb, 0, 'HbA1c reflects average glucose over about 3 months, so it indicates chronic hyperglycaemia.', 'GI, Endocrine & Metabolic', '🍽️'),
(386, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which patient is most at risk of developing MODS?', '["A 22-year-old with SLE and a pelvic fracture", "A 48-year-old with lung cancer and SIADH", "A 65-year-old with unstable angina", "An 82-year-old with diabetes and CKD admitted with dialysis-related peritonitis"]'::jsonb, 3, 'Advanced age, chronic kidney disease, diabetes and serious infection (peritonitis) together give the highest MODS risk.', 'Shock & Haemorrhage', '⚡'),
(387, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The following are key in managing MODS EXCEPT:', '["Prevention and treatment of infection", "Routine albumin infusion", "Nutrition and metabolic support", "Support of failing organs"]'::jsonb, 1, 'MODS management: prevent and treat infection, support failing organs, and meet nutritional and metabolic needs. Routine albumin is not a core measure.', 'Shock & Haemorrhage', '⚡'),
(388, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The first step in managing diabetic ketoacidosis is:', '["IV fluids", "Insulin", "Bicarbonate", "Insulin and fluids simultaneously"]'::jsonb, 0, 'The first step in DKA is IV fluid resuscitation. Insulin follows once potassium is known.', 'GI, Endocrine & Metabolic', '🍽️'),
(389, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The first counter-regulatory response to hypoglycaemia in normal people is:', '["Adrenaline release", "Glucagon release", "Inhibition of insulin release", "Growth hormone release"]'::jsonb, 2, 'In healthy people the first defence against falling glucose is suppression of insulin secretion, followed by glucagon then adrenaline.', 'GI, Endocrine & Metabolic', '🍽️'),
(390, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Predisposing factors for hypoglycaemia in insulin-treated patients include all EXCEPT:', '["Renal failure", "Young age", "Hypoglycaemia unawareness", "Alcohol ingestion"]'::jsonb, 1, 'Renal failure, hypoglycaemia unawareness and alcohol predispose to hypoglycaemia on insulin. Young age by itself does not.', 'GI, Endocrine & Metabolic', '🍽️'),
(391, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The LEAST important part of initial DKA treatment is:', '["Lowering blood glucose with insulin", "Giving fluids", "Giving sodium bicarbonate", "Giving potassium chloride"]'::jsonb, 2, 'Bicarbonate is rarely needed in DKA (only if pH <6.9). Fluids, insulin and potassium come first.', 'GI, Endocrine & Metabolic', '🍽️'),
(392, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Pressure ulcers affect:', '["The skin and/or underlying tissue", "The skin only", "Fat only", "Blood vessels only"]'::jsonb, 0, 'Pressure ulcers damage the skin and/or the underlying tissue, usually over a bony prominence.', 'Rehabilitation & Mobilization', '🏃'),
(393, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Patients at high risk of pressure ulcers should be identified:', '["After discharge", "On admission only", "During ongoing assessment only", "On admission and with ongoing assessment during hospitalisation"]'::jsonb, 3, 'Identify high-risk patients on admission and then reassess throughout the stay.', 'Rehabilitation & Mobilization', '🏃'),
(394, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which is UNTRUE about post-operative management of bladder trauma repair?', '["Follow-up cystography is recommended for high-risk patients", "Keep the urethral/suprapubic catheter for about 10–14 days", "Remove the pelvic drain when output is minimal", "Remove the catheter after 24 hours for comfort"]'::jsonb, 3, 'After bladder repair the catheter usually stays 7–14 days, with a cystogram before removal. Removing it at 24 hours risks leakage.', 'Renal & Fluid Balance', '💧'),
(395, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'In multidisciplinary management of bladder trauma, which specialist is usually NOT involved?', '["Orthopaedic surgeon", "Radiologist", "Urologist", "Oncologist"]'::jsonb, 3, 'Bladder trauma (often with pelvic fracture) involves urologists, radiologists and orthopaedic surgeons, not oncologists.', 'Burns & Trauma', '🔥'),
(396, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Operative management of extraperitoneal bladder rupture may be indicated in:', '["Concomitant rectal or vaginal injury", "Foreign body in the bladder wall", "Extensive bladder wall tear", "All of the above"]'::jsonb, 3, 'Extraperitoneal rupture usually heals with catheter drainage. Surgery is needed for associated rectal/vaginal injury, foreign bodies, bone fragments or extensive tears.', 'Burns & Trauma', '🔥'),
(397, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Storage lower urinary tract symptoms include the following EXCEPT:', '["Frequency", "Urgency", "Hesitancy", "Nocturia"]'::jsonb, 2, 'Storage symptoms are frequency, urgency, nocturia and urge incontinence. Hesitancy is a voiding symptom.', 'Renal & Fluid Balance', '💧'),
(398, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Voiding lower urinary tract symptoms include the following EXCEPT:', '["Incontinence", "Intermittency", "Incomplete bladder emptying", "Poor urinary stream"]'::jsonb, 0, 'Voiding symptoms are hesitancy, intermittency, poor stream and incomplete emptying. Incontinence is a storage symptom.', 'Renal & Fluid Balance', '💧'),
(399, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'A major risk factor for prostate cancer is:', '["Ethnicity (African descent)", "A diet rich in antioxidants", "Systemic hypertension", "Wealthy background"]'::jsonb, 0, 'Major prostate cancer risk factors are age, family history and ethnicity (higher in men of African descent).', 'Renal & Fluid Balance', '💧'),
(400, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Concerning the aetiology of BPH, which is WRONG?', '["Androgens are required for BPH to develop", "There is a genetic predisposition", "Sexual activity is a significant risk factor", "Age is a risk factor"]'::jsonb, 2, 'BPH needs androgens and has a genetic component. Sexual activity is not a risk factor.', 'Renal & Fluid Balance', '💧'),
(401, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The confirmatory investigation for prostate cancer is:', '["PSA test", "Prostate biopsy", "Prostate scan", "Multiparametric MRI"]'::jsonb, 1, 'Prostate biopsy (histology) confirms prostate cancer. PSA and MRI guide suspicion.', 'Renal & Fluid Balance', '💧'),
(402, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Complications of prostate cancer exclude:', '["Anaemia", "Bone pain", "Pathological fracture", "Improved appetite"]'::jsonb, 3, 'Advanced prostate cancer causes anaemia, bone pain and pathological fractures, and LOSS of appetite.', 'Renal & Fluid Balance', '💧'),
(403, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which is NOT a nursing priority in BPH?', '["Pain management", "Promotion of urinary incontinence", "Collaboration for diagnostic tests and treatment", "Assessment of urinary symptoms and flow"]'::jsonb, 1, 'BPH priorities: pain, assessing urinary symptoms, and collaborating on investigations. Promoting incontinence is never a goal.', 'Renal & Fluid Balance', '💧'),
(404, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Hirschsprung''s disease is also known as:', '["Congenital (aganglionic) megacolon", "Ganglionic megacolon", "Polyganglionic colon", "Ganglionic intestine"]'::jsonb, 0, 'Hirschsprung''s disease (aganglionic or congenital megacolon) lacks ganglion cells in a bowel segment.', 'Obstetric & Neonatal', '🤱'),
(405, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Pre-operative care in Hirschsprung''s disease includes the following EXCEPT:', '["Giving oral feeds", "Taking vital signs", "Measuring abdominal girth", "Nasogastric decompression"]'::jsonb, 0, 'Pre-op Hirschsprung''s care: nil by mouth, NG decompression, vital signs, abdominal girth and bowel washouts. Oral feeds are withheld.', 'Obstetric & Neonatal', '🤱'),
(406, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which is part of pre-operative care for a child with Hirschsprung''s disease?', '["CT scan", "Shaving the axillary hair", "Giving bowel washouts/enemas", "Obtaining consent from the child himself"]'::jsonb, 2, 'Rectal washouts or enemas decompress the bowel before surgery in Hirschsprung''s disease.', 'Obstetric & Neonatal', '🤱'),
(407, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which is NOT done for a Hirschsprung''s patient post-operatively?', '["Monitoring vital signs", "Monitoring bleeding from the wound", "Colostomy care", "Applying zinc oxide to the chest"]'::jsonb, 3, 'Post-op care: vital signs, wound bleeding and stoma care. Zinc oxide goes on peristomal skin, not the chest.', 'Obstetric & Neonatal', '🤱'),
(408, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which statement about intussusception is FALSE?', '["It usually occurs in healthy babies without a demonstrable cause", "It is mostly found in adolescents", "It most commonly occurs at the ileocolic junction", "The proximal bowel telescopes into the distal bowel"]'::jsonb, 1, 'Intussusception is most common in infants of 6–18 months, usually ileocolic and often without a clear cause. It is not mainly an adolescent disease.', 'Obstetric & Neonatal', '🤱'),
(409, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Management of intussusception includes all EXCEPT:', '["IV fluids", "Therapeutic (air/contrast) enema", "Surgical reduction", "Radiotherapy"]'::jsonb, 3, 'Intussusception is managed with IV fluids, reduction by air or contrast enema, or surgery. Radiotherapy has no role.', 'Obstetric & Neonatal', '🤱'),
(410, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which is NOT a complication of appendicitis?', '["Type 1 diabetes mellitus", "Perforation", "Shock", "Pelvic abscess"]'::jsonb, 0, 'Appendicitis can perforate, causing peritonitis, abscess and shock. Type 1 diabetes is unrelated.', 'GI, Endocrine & Metabolic', '🍽️'),
(411, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The most common cause of croup is:', '["Viral infection (parainfluenza)", "Bacterial infection", "Allergic reaction", "Trauma"]'::jsonb, 0, 'Croup (laryngotracheobronchitis) is usually viral, most often parainfluenza.', 'Respiratory', '🫁'),
(412, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'A characteristic sign of croup is:', '["A barking cough with inspiratory stridor", "A productive cough with green sputum", "Expiratory wheeze only", "High fever with drooling"]'::jsonb, 0, 'Croup''s hallmarks are a barking (seal-like) cough, hoarseness and inspiratory stridor.', 'Respiratory', '🫁'),
(413, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The typical age range for croup is:', '["1–3 months", "6 months to 3 years", "5–10 years", "10–15 years"]'::jsonb, 1, 'Croup peaks between 6 months and 3 years of age.', 'Respiratory', '🫁'),
(414, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'A local cause of bleeding in pregnancy is:', '["Carcinoma of the cervix", "Hypotension", "Diabetes mellitus", "Anaemia"]'::jsonb, 0, 'Vasa praevia and cervical lesions (polyps, carcinoma) are local causes of bleeding in pregnancy.', 'Obstetric & Neonatal', '🤱'),
(415, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which is NOT a risk factor for placenta praevia?', '["Multiparity", "Hypertension", "Large placental surface", "Uterine fibroids"]'::jsonb, 1, 'Placenta praevia risk factors: multiparity, previous caesarean section or uterine surgery, a large placenta (twins), fibroids and smoking. Hypertension is a risk for abruption.', 'Obstetric & Neonatal', '🤱'),
(416, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'A symptom of abruptio placentae is:', '["Painful vaginal bleeding", "Headache", "Fever", "Parasitaemia"]'::jsonb, 0, 'Abruption causes painful vaginal bleeding (revealed) with a tense, tender uterus.', 'Obstetric & Neonatal', '🤱'),
(417, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Abruptio placentae can be classified into:', '["Revealed", "Concealed", "Mixed", "All of the above"]'::jsonb, 3, 'Abruption is classified clinically as revealed, concealed or mixed.', 'Obstetric & Neonatal', '🤱'),
(418, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Cervical incompetence is when the cervical tissue is:', '["Firm and long", "Weak", "Thickened by fibroids", "Fully closed"]'::jsonb, 1, 'Cervical incompetence is weakness of the cervical tissue, leading to painless dilatation in the second trimester.', 'Obstetric & Neonatal', '🤱'),
(419, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The difference between placenta praevia and abruption is:', '["In praevia the placenta covers or lies near the cervix; in abruption a normally sited placenta separates from the uterine wall", "In praevia the placenta separates; in abruption it covers the cervix", "They are the same condition", "Neither involves bleeding"]'::jsonb, 0, 'Placenta praevia is a placenta covering or near the cervical os. Abruption is premature separation of a normally sited placenta from the uterine wall.', 'Obstetric & Neonatal', '🤱'),
(420, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Placental abruption is separation of the placenta:', '["After delivery of the baby", "Before delivery of the baby", "Only during the third stage", "Never before labour"]'::jsonb, 1, 'Abruption is partial or complete separation of the placenta before delivery of the baby.', 'Obstetric & Neonatal', '🤱'),
(421, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Corticosteroids are given to a mother whose delivery is planned before 37 weeks to:', '["Help the baby''s lungs mature", "Prepare the cervix for delivery", "Prevent maternal fits", "Keep the mother calm"]'::jsonb, 0, 'Antenatal corticosteroids (dexamethasone/betamethasone) before 34–37 weeks speed fetal lung maturation and reduce RDS.', 'Obstetric & Neonatal', '🤱'),
(422, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Hypotension in pregnancy is defined as a blood pressure below:', '["90/60 mmHg", "100/70 mmHg", "110/80 mmHg", "120/90 mmHg"]'::jsonb, 0, 'Hypotension in pregnancy is usually defined as BP below 90/60 mmHg.', 'Obstetric & Neonatal', '🤱'),
(423, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The commonest operation for a ruptured tubal pregnancy is:', '["Total hysterectomy", "Salpingostomy", "Salpingectomy", "Salpingo-oophorectomy"]'::jsonb, 2, 'A ruptured tubal pregnancy with haemorrhage is usually treated by salpingectomy (removing the tube).', 'Obstetric & Neonatal', '🤱'),
(424, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'All are signs of ruptured ectopic pregnancy EXCEPT:', '["Tachycardia, shock, pallor and collapse", "Hyperglycaemia", "Abdominal pain", "Vaginal bleeding"]'::jsonb, 1, 'Ruptured ectopic causes pain, vaginal bleeding, shock, pallor and tachycardia. Hyperglycaemia is not a feature.', 'Obstetric & Neonatal', '🤱'),
(425, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The definitive (gold-standard) method of confirming ectopic pregnancy is:', '["Ultrasound", "Laparoscopy", "Urine pregnancy test", "HSG"]'::jsonb, 1, 'Transvaginal ultrasound with serum β-hCG is the main diagnostic tool. Laparoscopy is the definitive (gold-standard) confirmation.', 'Obstetric & Neonatal', '🤱'),
(426, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which is/are positive findings in ectopic pregnancy?', '["Cervical excitation tenderness", "Positive pregnancy test", "Vaginal bleeding", "All of the above"]'::jsonb, 3, 'Cervical excitation, a positive pregnancy test and PV bleeding are all typical of ectopic pregnancy.', 'Obstetric & Neonatal', '🤱'),
(427, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'MEOWS stands for:', '["Moment Evaluation of Obstetric Syndrome", "Modified Early Obstetric Warning Signs", "Modified Early Obstetric Warning Score", "Maternal Early Warning Signs"]'::jsonb, 2, 'MEOWS is the Modified Early Obstetric Warning Score, used to detect deterioration in pregnant and postnatal women.', 'Obstetric & Neonatal', '🤱'),
(428, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'An acute event involving the cardiorespiratory and/or central nervous system that causes reduced or absent consciousness in pregnancy is:', '["Maternal collapse", "Ectopic pregnancy", "Hyperemesis gravidarum", "Placenta praevia"]'::jsonb, 0, 'Maternal collapse is an acute cardiorespiratory and/or CNS event causing reduced or absent consciousness, at any stage of pregnancy up to 6 weeks after delivery.', 'Obstetric & Neonatal', '🤱'),
(429, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'HELLP syndrome is:', '["A complication of severe pre-eclampsia", "A type of fetal growth restriction", "A form of gestational hypertension only", "An inherited maternal coagulopathy"]'::jsonb, 0, 'HELLP (Haemolysis, Elevated Liver enzymes, Low Platelets) is a severe complication of pre-eclampsia.', 'Obstetric & Neonatal', '🤱'),
(430, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Clinical features of hyperemesis gravidarum include all EXCEPT:', '["Vomiting more than 3–4 times a day", "Weight loss of more than 5%", "Dizziness", "Insomnia"]'::jsonb, 3, 'Hyperemesis causes persistent vomiting, weight loss over 5%, dehydration and dizziness. Insomnia is not a defining feature.', 'Obstetric & Neonatal', '🤱'),
(431, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The following are risk factors for leukaemia EXCEPT:', '["Ultrasonography", "Ionising radiation", "Smoking", "Race/genetics"]'::jsonb, 0, 'Ultrasonography uses no ionising radiation and is not a leukaemia risk. Radiation, smoking and genetic or racial factors are.', 'Laboratory Sciences & Haematology', '🔬'),
(432, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The following are types of leukaemia EXCEPT:', '["ALL", "AML", "CLM", "CLL"]'::jsonb, 2, 'The four main leukaemias are ALL, AML, CLL and CML. "CLM" is not a classification.', 'Laboratory Sciences & Haematology', '🔬'),
(433, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Clinical features of epiglottitis include all EXCEPT:', '["Hypothermia", "Sore throat", "Tripod posture", "Drooling"]'::jsonb, 0, 'Epiglottitis causes fever (not hypothermia), sore throat, drooling and tripod posture.', 'Respiratory', '🫁'),
(434, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Complications of epiglottitis include:', '["Respiratory failure", "Cardiac arrest", "Sepsis", "All of the above"]'::jsonb, 3, 'Epiglottitis can cause airway obstruction and respiratory failure, cardiac arrest and sepsis.', 'Respiratory', '🫁'),
(435, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The typical age for epiglottitis in children is:', '["1–3 months", "2–5 years", "5–10 years", "10–15 years"]'::jsonb, 1, 'Classic (Hib) epiglottitis peaked at 2–5 years. It is now rarer and seen more in adults since vaccination.', 'Respiratory', '🫁'),
(436, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Which advice should a critical care nurse give the relatives of a patient with a colostomy?', '["Not to have another child", "Not to remove the bag until it peels off", "Teach them colostomy care", "To be very worried until recovery"]'::jsonb, 2, 'Families should be taught colostomy care: emptying and changing the bag, skin care and spotting complications.', 'GI, Endocrine & Metabolic', '🍽️'),
(437, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'Colostomy care includes the following EXCEPT:', '["Putting the patient in lithotomy position", "Keeping the skin around the stoma clean", "Frequent emptying of the colostomy bag", "Protecting the peristomal skin"]'::jsonb, 0, 'Colostomy care: keep peristomal skin clean, empty the bag often, protect the skin (e.g. zinc oxide). Lithotomy position is not needed.', 'GI, Endocrine & Metabolic', '🍽️'),
(438, 'UMTH Prequalifying Practice Set 7', 'UMTH Critical Care Nursing Programme prequalifying practice questions, set 7 (uploaded)', 'The congenital condition with a lack of nerve cells in segments of the large intestine is:', '["Ganglionic colon", "Mega-intestine", "Aganglionic megacolon", "Intussusception"]'::jsonb, 2, 'Aganglionic megacolon (Hirschsprung''s) is the congenital absence of nerve (ganglion) cells in part of the large bowel.', 'Obstetric & Neonatal', '🤱'),
(439, 'Electrical Cardioversion', 'Original questions written from the uploaded UMTH cardioversion checklist and questions', 'Electrical cardioversion is best defined as:', '["An unsynchronised shock for ventricular fibrillation", "A synchronised electrical shock, timed to the R wave, to restore sinus rhythm in a tachyarrhythmia", "Insertion of a permanent pacemaker", "Chest compressions with drug therapy"]'::jsonb, 1, 'Cardioversion is a synchronised DC shock, timed to the R wave, that converts a tachyarrhythmia (e.g. AF, flutter, SVT, VT with a pulse) to sinus rhythm.', 'Cardiovascular', '🫀'),
(440, 'Electrical Cardioversion', 'Original questions written from the uploaded UMTH cardioversion checklist and questions', 'Why is the cardioversion shock synchronised to the R wave?', '["To deliver more energy", "To avoid shocking on the T wave, which can trigger ventricular fibrillation", "To shorten the procedure", "To prevent skin burns"]'::jsonb, 1, 'Synchronising the shock to the R wave avoids the T wave (the vulnerable period of repolarisation). A shock on the T wave can trigger VF.', 'Cardiovascular', '🫀'),
(441, 'Electrical Cardioversion', 'Original questions written from the uploaded UMTH cardioversion checklist and questions', 'Which arrhythmia is treated with synchronised cardioversion rather than defibrillation?', '["Ventricular fibrillation", "Pulseless VT", "Atrial fibrillation", "Asystole"]'::jsonb, 2, 'Elective cardioversion suits AF, atrial flutter, SVT and VT with a pulse. Pulseless VT and VF need unsynchronised defibrillation.', 'Cardiovascular', '🫀'),
(442, 'Electrical Cardioversion', 'Original questions written from the uploaded UMTH cardioversion checklist and questions', 'Before elective cardioversion, digoxin is usually withheld for about:', '["48 hours", "1 hour", "2 weeks", "It is never withheld"]'::jsonb, 0, 'Digoxin is usually withheld for about 48 hours before elective cardioversion because digoxin toxicity raises the risk of post-shock arrhythmias.', 'Cardiovascular', '🫀'),
(443, 'Electrical Cardioversion', 'Original questions written from the uploaded UMTH cardioversion checklist and questions', 'Before elective cardioversion the patient should:', '["Eat a heavy meal", "Fast (nil by mouth) for about 6–12 hours", "Drink only coffee", "Stop all IV access"]'::jsonb, 1, 'Patients fast for about 6–12 hours because sedation or anaesthesia is given (aspiration risk).', 'Cardiovascular', '🫀'),
(444, 'Electrical Cardioversion', 'Original questions written from the uploaded UMTH cardioversion checklist and questions', 'Before delivering cardioversion, the nurse must confirm that:', '["The machine is sensing (marking) the R wave in sync mode", "The defibrillator is in unsynchronised mode", "Oxygen is flowing over the chest", "The patient is awake and talking"]'::jsonb, 0, 'Press SYNC and confirm the machine marks each R wave before charging. Without sensing, the shock may land on the T wave.', 'Cardiovascular', '🫀'),
(445, 'Electrical Cardioversion', 'Original questions written from the uploaded UMTH cardioversion checklist and questions', 'Immediately before discharging the shock in cardioversion, the operator should:', '["Hold the patient''s hand", "Shout \"clear\" and ensure no one is touching the patient or bed", "Turn off the ECG monitor", "Remove the IV line"]'::jsonb, 1, 'Everyone must stand clear before discharge ("I''m clear, you''re clear, everyone''s clear"), with oxygen moved away, to prevent shocks and fire.', 'Cardiovascular', '🫀'),
(446, 'Electrical Cardioversion', 'Original questions written from the uploaded UMTH cardioversion checklist and questions', 'After a cardioversion shock, the nurse should first:', '["Leave the bedside", "Reassess the rhythm and vital signs for correction of the arrhythmia", "Remove the IV cannula", "Give the patient food"]'::jsonb, 1, 'After the shock, reassess rhythm, pulse, BP and SpO2. If it fails, the shock may be repeated at higher energy as ordered.', 'Cardiovascular', '🫀'),
(447, 'Electrical Cardioversion', 'Original questions written from the uploaded UMTH cardioversion checklist and questions', 'Gel or conductive pads are applied for cardioversion to:', '["Reduce skin resistance and prevent burns", "Make the paddles stick for longer", "Cool the chest", "Measure blood pressure"]'::jsonb, 0, 'Conducting gel or pads reduce skin resistance and prevent burns, and improve current delivery.', 'Cardiovascular', '🫀')
) as v(n, topic, source, q, opts, ans_idx, exp, category, category_icon)
where not exists (
  select 1 from public.questions x
  where regexp_replace(lower(x.q), '[^a-z0-9]', '', 'g') = regexp_replace(lower(v.q), '[^a-z0-9]', '', 'g')
);
